// The call's video transceiver, but only once setRemoteDescription has bound it
// to an m-section (mid !== null). An unassociated transceiver still exposes a
// usable-looking sender whose replaceTrack() resolves without ever putting media
// on the wire, so matching on `mid` is what keeps screen sharing from failing
// silently.
const findAssociatedCallVideoTransceiver = (peerConnection) => (
  peerConnection?.getTransceivers?.().find((transceiver) => (
    transceiver.mid !== null &&
    !transceiver.stopped &&
    transceiver.receiver?.track?.kind === 'video'
  )) || null
);

const findAssociatedCallAudioTransceiver = (peerConnection) => (
  peerConnection?.getTransceivers?.().find((transceiver) => (
    transceiver.mid !== null &&
    !transceiver.stopped &&
    transceiver.receiver?.track?.kind === 'audio'
  )) || null
);

const findReusableCallAudioTransceiver = (peerConnection) => (
  peerConnection?.getTransceivers?.().find((transceiver) => (
    !transceiver.stopped &&
    transceiver.receiver?.track?.kind === 'audio' &&
    (!transceiver.sender?.track || transceiver.sender.track.kind === 'audio')
  )) || null
);

// Human-friendly timestamp for a call-log row: "Today, 4:05 PM" / "Yesterday,
// ..." / "12 Jun, ...". Returns '' for a missing/unparseable value.
const formatCallLogTimestamp = (value) => {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) {
    return '';
  }
  const now = new Date();
  const time = date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  if (date.toDateString() === now.toDateString()) {
    return `Today, ${time}`;
  }
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (date.toDateString() === yesterday.toDateString()) {
    return `Yesterday, ${time}`;
  }
  return `${date.toLocaleDateString([], { day: '2-digit', month: 'short' })}, ${time}`;
};

const formatCallHistoryTime = (value) => {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) {
    return '';
  }

  return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
};

const formatCallHistoryDayLabel = (value) => {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) {
    return 'Earlier';
  }

  const now = new Date();
  if (date.toDateString() === now.toDateString()) {
    return 'Today';
  }

  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (date.toDateString() === yesterday.toDateString()) {
    return 'Yesterday';
  }

  return date.toLocaleDateString([], { month: 'long', day: 'numeric', year: 'numeric' });
};

const normalizeCallHistoryType = (value) =>
  String(value || '').trim().toLowerCase() === CALL_TYPE.VIDEO ? CALL_TYPE.VIDEO : CALL_TYPE.AUDIO;

const getEntityId = (entity) =>
  String(entity?._id || entity?.id || entity?.userId || entity || '').trim();

const resolveCallDirectionFromParticipants = ({
  currentUserId = '',
  callerId = '',
  receiverId = '',
} = {}) => {
  const normalizedCurrentUserId = String(currentUserId || '').trim();
  if (!normalizedCurrentUserId) {
    return '';
  }

  if (String(callerId || '').trim() === normalizedCurrentUserId) {
    return CALL_LOG_DIRECTION.OUTGOING;
  }

  if (String(receiverId || '').trim() === normalizedCurrentUserId) {
    return CALL_LOG_DIRECTION.INCOMING;
  }

  return '';
};

const resolveBackendCallDirection = (
  call = {},
  currentUserId = '',
  { callerId = '', receiverId = '' } = {}
) => {
  const explicitDirection = normalizeCallLogDirection(
    call?.direction ||
      call?.callDirection ||
      call?.call_direction ||
      call?.metadata?.direction ||
      call?.metadata?.callDirection,
    ''
  );
  if (explicitDirection) {
    return explicitDirection;
  }

  const incomingFlag = call?.incoming ?? call?.isIncoming ?? call?.metadata?.incoming;
  if (incomingFlag === true) {
    return CALL_LOG_DIRECTION.INCOMING;
  }
  if (incomingFlag === false) {
    return CALL_LOG_DIRECTION.OUTGOING;
  }

  const outgoingFlag = call?.outgoing ?? call?.isOutgoing ?? call?.metadata?.outgoing;
  if (outgoingFlag === true) {
    return CALL_LOG_DIRECTION.OUTGOING;
  }
  if (outgoingFlag === false) {
    return CALL_LOG_DIRECTION.INCOMING;
  }

  return resolveCallDirectionFromParticipants({
    currentUserId,
    callerId: callerId || getEntityId(call?.callerId || call?.caller),
    receiverId: receiverId || getEntityId(call?.receiverId || call?.receiver),
  });
};
const getCallLogSortTimestamp = (log = {}) => {
  const timestamp = new Date(log.endedAt || log.startedAt || 0).getTime();
  return Number.isFinite(timestamp) ? timestamp : 0;
};

const mergeCallHistoryLogs = (...logLists) => {
  const logsById = new Map();

  logLists.flat().filter(Boolean).forEach((log) => {
    const normalizedLog = createCallLog(log);
    if (isCallLogDeleted(normalizedLog.callId)) {
      return;
    }
    logsById.set(normalizedLog.callId, normalizedLog);
  });

  return Array.from(logsById.values()).sort(
    (firstLog, secondLog) => getCallLogSortTimestamp(secondLog) - getCallLogSortTimestamp(firstLog)
  );
};

const normalizeBackendCallHistory = (payload = {}, currentUserId = '') => {
  const normalizedCurrentUserId = String(currentUserId || '').trim();
  const personalCalls = Array.isArray(payload?.personalCalls) ? payload.personalCalls : [];
  const groupCalls = Array.isArray(payload?.groupCalls) ? payload.groupCalls : [];

  const normalizedPersonalCalls = personalCalls.map((call) => {
    const callerId = getEntityId(call?.caller);
    const receiverId = getEntityId(call?.receiver);
    const isCurrentUserCaller = Boolean(normalizedCurrentUserId && callerId === normalizedCurrentUserId);
    const peer = isCurrentUserCaller ? call?.receiver : call?.caller;
    const peerId = getEntityId(peer) || (isCurrentUserCaller ? receiverId : callerId);

    return createCallLog({
      callId: call?._id || call?.id,
      contactId: peerId || call?.chat,
      // Only a real profile name: an account that never set one used to fall back
      // to its raw user id here, which the Calls history then showed as the name.
      // The history row resolves a readable name from the user's chats instead.
      contactName: peer?.name || peer?.fullName || '',
      avatar: peer?.profilePic || peer?.profilePicture || peer?.avatar || peer?.avatarUrl || '',
      callType: call?.type,
      duration: call?.duration,
      status: call?.status,
      direction: resolveBackendCallDirection(call, normalizedCurrentUserId, { callerId, receiverId }),
      startedAt: call?.startedAt || call?.createdAt,
      endedAt: call?.endedAt || call?.updatedAt || call?.startedAt || call?.createdAt,
    });
  });

  const normalizedGroupCalls = groupCalls.map((call) => {
    const group = call?.groupId && typeof call.groupId === 'object' ? call.groupId : {};
    const groupId = getEntityId(group) || getEntityId(call?.groupId) || call?._id || call?.id;
    // A group call has no caller/receiver pair, only the member who started it:
    // anyone else joined it, so it is incoming for them rather than "Outgoing".
    const startedById = getEntityId(call?.startedBy);

    return createCallLog({
      callId: call?._id || call?.id,
      contactId: groupId,
      contactName: group?.groupName || group?.name || call?.groupName || 'Conference Call',
      avatar: group?.groupProfilePic || group?.groupPhoto || group?.profilePic || '',
      callType: call?.type || CALL_TYPE.VIDEO,
      isGroup: true,
      duration: call?.duration,
      status: call?.status === 'ended' ? CALL_LOG_STATUS.COMPLETED : call?.status,
      direction:
        resolveBackendCallDirection(call, normalizedCurrentUserId, { callerId: startedById }) ||
        (startedById && normalizedCurrentUserId ? CALL_LOG_DIRECTION.INCOMING : ''),
      startedAt: call?.startedAt || call?.createdAt,
      endedAt: call?.endedAt || call?.updatedAt || call?.startedAt || call?.createdAt,
    });
  });

  return mergeCallHistoryLogs(normalizedPersonalCalls, normalizedGroupCalls);
};

// Label + colour for a call-log status. Missed/Declined read red; a completed
// call is green and shows its duration alongside.
const getCallLogStatusMeta = (status, direction = '') => {
  const normalizedDirection = normalizeCallLogDirection(direction);

  switch (status) {
    case CALL_LOG_STATUS.MISSED:
      return normalizedDirection === CALL_LOG_DIRECTION.OUTGOING
        ? { label: 'Outgoing – Not Answered', className: 'text-[#EF4444]' }
        : { label: 'Missed', className: 'text-[#EF4444]' };
    case CALL_LOG_STATUS.REJECTED:
      return { label: 'Declined', className: 'text-[#EF4444]' };
    default:
      return normalizedDirection === CALL_LOG_DIRECTION.INCOMING
        ? { label: 'Incoming', className: 'text-[#3B82F6]' }
        : { label: 'Outgoing', className: 'text-[#16A34A]' };
  }
};

const isCallNetworkReady = () => {
  const socketSnapshot = socketService.getSnapshot();
  return (
    (typeof navigator === 'undefined' || navigator.onLine) &&
    Boolean(socketSnapshot?.isConnected && socketSnapshot?.status === 'connected')
  );
};

const resolveIncomingCallTimeoutDeadline = (incomingCall = {}) => {
  const parsedStartedAtMs = new Date(
    incomingCall?.startedAt ||
      incomingCall?.timestamp ||
      incomingCall?.createdAt ||
      Date.now()
  ).getTime();
  const safeStartedAtMs = Number.isFinite(parsedStartedAtMs)
    ? parsedStartedAtMs
    : Date.now();
  return safeStartedAtMs + INCOMING_CALL_RING_TIMEOUT_MS;
};

const getRemainingIncomingCallTimeoutMs = (timeoutDeadlineMs, now = Date.now()) => {
  if (!Number.isFinite(timeoutDeadlineMs) || timeoutDeadlineMs <= 0) {
    return 0;
  }

  return Math.max(0, timeoutDeadlineMs - now);
};

const resolveIncomingCallPayloadFromSearch = (search = '', chatId = '') => {
  const params = new URLSearchParams(String(search || ''));
  if (params.get('incomingCall') !== '1') return null;

  const normalizedChatId = String(chatId || '').trim();
  if (!normalizedChatId) return null;

  return {
    kind: 'incoming-call',
    callId: String(params.get('callId') || '').trim(),
    chatId: normalizedChatId,
    callerId: String(params.get('callerId') || '').trim(),
    senderId: String(params.get('callerId') || '').trim(),
    callerName: String(params.get('callerName') || '').trim(),
    senderName: String(params.get('callerName') || '').trim(),
    callType: String(params.get('callType') || CALL_TYPE.AUDIO).trim().toLowerCase(),
    startedAt: String(params.get('startedAt') || '').trim() || new Date().toISOString(),
    profilePic: String(params.get('profilePic') || '').trim(),
  };
};

const resolveCallHistoryNotificationFromSearch = (search = '') => {
  const params = new URLSearchParams(String(search || ''));
  if (params.get('callHistory') !== '1') return null;

  return {
    kind: 'missed_call',
    messageType: 'call',
    callId: String(params.get('callId') || '').trim(),
    callerId: String(params.get('callerId') || '').trim(),
    senderId: String(params.get('callerId') || '').trim(),
    callerName: String(params.get('callerName') || '').trim(),
    senderName: String(params.get('callerName') || '').trim(),
    callType: String(params.get('callType') || CALL_TYPE.AUDIO).trim().toLowerCase(),
    callStatus: String(params.get('callStatus') || 'missed').trim().toLowerCase(),
    startedAt: String(params.get('startedAt') || '').trim() || new Date().toISOString(),
    timestamp: String(params.get('startedAt') || '').trim() || new Date().toISOString(),
    profilePic: String(params.get('profilePic') || '').trim(),
  };
};

const resolveIncomingRouteCallType = (locationState = {}, incomingCallPayload = null) => {
  const directType = String(
    locationState?.callType ||
    incomingCallPayload?.callType ||
    incomingCallPayload?.mediaType ||
    incomingCallPayload?.mode ||
    incomingCallPayload?.callMode ||
    incomingCallPayload?.call?.callType ||
    incomingCallPayload?.call?.mediaType ||
    ''
  ).trim().toLowerCase();
  if (directType === CALL_TYPE.VIDEO) return CALL_TYPE.VIDEO;
  if (directType === CALL_TYPE.AUDIO) return CALL_TYPE.AUDIO;
  if (incomingCallPayload?.isVideo === true || incomingCallPayload?.video === true) return CALL_TYPE.VIDEO;
  const typeHint = String([
    incomingCallPayload?.type,
    incomingCallPayload?.title,
    incomingCallPayload?.body,
    incomingCallPayload?.message,
    incomingCallPayload?.text,
  ].filter(Boolean).join(' ')).trim().toLowerCase();
  return /\bvideo\b/.test(typeHint) ? CALL_TYPE.VIDEO : CALL_TYPE.AUDIO;
};

const formatChatListPreviewText = (value = '') => {
  const normalizedText = String(value || '').trim().replace(/\s+/g, ' ');
  if (!normalizedText) return '';
  if (isMessageReactionControlText(normalizedText)) return '';

  if (normalizedText.length <= CHAT_LIST_PREVIEW_CHARACTER_LIMIT) return normalizedText;

  return `${normalizedText.slice(0, CHAT_LIST_PREVIEW_CHARACTER_LIMIT)}...`;
};

const formatBroadcastListPreviewText = (value = '') => {
  const previewItems = (Array.isArray(value) ? value : String(value || '').split(/\r?\n+/))
    .map((item) => String(item || '').trim().replace(/\s+/g, ' '))
    .filter(Boolean);

  return formatChatListPreviewText(previewItems.join(', '));
};

const MESSAGE_REACTION_CONTROL_PREFIX = '__CHATTERLY_MESSAGE_REACTION__:';
const BROADCAST_MEDIA_CONTROL_PREFIX = '__CHATTERLY_BROADCAST_MEDIA__:';

const isMessageReactionControlText = (value = '') =>
  String(value || '').trim().startsWith(MESSAGE_REACTION_CONTROL_PREFIX);

const parseMessageReactionControlText = (value = '') => {
  const normalizedValue = String(value || '').trim();
  if (!isMessageReactionControlText(normalizedValue)) {
    return null;
  }

  try {
    const payload = JSON.parse(normalizedValue.slice(MESSAGE_REACTION_CONTROL_PREFIX.length));
    return payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : null;
  } catch (error) {
    console.error('Unable to parse message reaction control payload:', error);
    return null;
  }
};

const getMessageReactionControlPayload = (message = {}) =>
  parseMessageReactionControlText(
    message?.content ||
      message?.text ||
      message?.message ||
      ''
  );

const buildMessageReactionControlText = (payload = {}) =>
  `${MESSAGE_REACTION_CONTROL_PREFIX}${JSON.stringify(payload)}`;

const buildBroadcastMediaControlText = (message = {}) =>
  `${BROADCAST_MEDIA_CONTROL_PREFIX}${JSON.stringify({
    type: String(message?.type || message?.mediaType || '').trim().toLowerCase(),
    mediaUrl: String(
      message?.mediaUrl || message?.fileUrl || message?.audioUrl || message?.content || ''
    ).trim(),
    fileName: String(message?.fileName || '').trim(),
    fileSize: Number(message?.fileSize || 0),
    mimeType: String(message?.mimeType || '').trim(),
    caption: String(message?.caption || '').trim(),
    duration: Number(message?.duration || 0),
  })}`;

const splitReactionControlMessages = (messages = []) =>
  (Array.isArray(messages) ? messages : []).reduce(
    (result, message) => {
      const payload = getMessageReactionControlPayload(message);
      if (payload) {
        result.reactionPayloads.push({
          ...payload,
          chatId: payload.chatId || message?.chatId || '',
          senderId: payload.senderId || message?.senderId || '',
          receiverId: payload.receiverId || message?.receiverId || '',
        });
        return result;
      }

      result.visibleMessages.push(message);
      return result;
    },
    { visibleMessages: [], reactionPayloads: [] }
  );

const resolveMessageDeleteTimestampValue = (message = {}) => {
  const timestampCandidates = [
    message?.timestamp,
    message?.createdAt,
    message?.updatedAt,
    message?.sentAt,
  ];

  for (const candidate of timestampCandidates) {
    if (!candidate) {
      continue;
    }

    const parsedTimestamp = new Date(candidate).getTime();
    if (Number.isFinite(parsedTimestamp)) {
      return parsedTimestamp;
    }
  }

  return null;
};

const canDeleteMessageForEveryone = (message = {}) => {
  const messageDirection = String(message?.direction || '').trim().toLowerCase();
  if (messageDirection && messageDirection !== 'sent') {
    return false;
  }

  const messageTimestamp = resolveMessageDeleteTimestampValue(message);
  if (!Number.isFinite(messageTimestamp)) {
    return true;
  }

  return messageTimestamp >= Date.now() - MESSAGE_DELETE_FOR_EVERYONE_WINDOW_MS;
};

const buildAudioWaveformHeights = async (audioBlob, barCount = WAVEFORM_HEIGHTS.length) => {
  try {
    const AudioContextConstructor =
      typeof window !== 'undefined' ? window.AudioContext || window.webkitAudioContext : null;
    if (!audioBlob?.size || !AudioContextConstructor) return WAVEFORM_HEIGHTS;

    const audioContext = new AudioContextConstructor();
    const arrayBuffer = await audioBlob.arrayBuffer();
    const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
    const channelData = audioBuffer.getChannelData(0);
    const samplesPerBar = Math.max(1, Math.floor(channelData.length / barCount));
    const amplitudes = Array.from({ length: barCount }, (_, index) => {
      const start = index * samplesPerBar;
      const end = Math.min(channelData.length, start + samplesPerBar);
      let sum = 0;
      for (let sampleIndex = start; sampleIndex < end; sampleIndex += 1) {
        sum += channelData[sampleIndex] * channelData[sampleIndex];
      }
      return Math.sqrt(sum / Math.max(1, end - start));
    });
    const peak = Math.max(...amplitudes, 0.01);
    await audioContext.close?.();
    return amplitudes.map((amplitude) => Math.max(4, Math.round(4 + (amplitude / peak) * 44)));
  } catch (error) {
    console.error('Unable to build audio waveform preview:', error);
    return WAVEFORM_HEIGHTS;
  }
};

const getBrowserMediaRecorderConstructor = () => {
  if (typeof window !== 'undefined') {
    return window.MediaRecorder || window.webkitMediaRecorder || null;
  }

  return typeof MediaRecorder !== 'undefined' ? MediaRecorder : null;
};

const getBrowserAudioInputStream = (constraints = { audio: true }) => {
  if (typeof navigator === 'undefined') {
    return Promise.reject(Object.assign(new Error('Media devices are unavailable.'), { name: 'NotSupportedError' }));
  }

  if (navigator.mediaDevices?.getUserMedia) {
    return navigator.mediaDevices.getUserMedia(constraints);
  }

  const legacyGetUserMedia =
    navigator.getUserMedia ||
    navigator.webkitGetUserMedia ||
    navigator.mozGetUserMedia ||
    navigator.msGetUserMedia;

  if (legacyGetUserMedia) {
    return new Promise((resolve, reject) => {
      legacyGetUserMedia.call(navigator, constraints, resolve, reject);
    });
  }

  return Promise.reject(Object.assign(new Error('Audio recording is unavailable.'), { name: 'NotSupportedError' }));
};

const isBrowserAudioInputSupported = () => {
  if (typeof navigator === 'undefined') return false;
  return Boolean(
    navigator.mediaDevices?.getUserMedia ||
      navigator.getUserMedia ||
      navigator.webkitGetUserMedia ||
      navigator.mozGetUserMedia ||
      navigator.msGetUserMedia
  );
};

const getSupportedVoiceRecordingMimeType = (MediaRecorderConstructor = getBrowserMediaRecorderConstructor()) => {
  if (!MediaRecorderConstructor || typeof MediaRecorderConstructor.isTypeSupported !== 'function') {
    return '';
  }

  return VOICE_RECORDING_MIME_TYPES.find((mimeType) => {
    try {
      return MediaRecorderConstructor.isTypeSupported(mimeType);
    } catch {
      return false;
    }
  }) || '';
};

const createVoiceMediaRecorder = (stream, mimeType = '') => {
  const MediaRecorderConstructor = getBrowserMediaRecorderConstructor();
  if (!MediaRecorderConstructor) {
    throw Object.assign(new Error('MediaRecorder is unavailable.'), { name: 'NotSupportedError' });
  }

  if (mimeType) {
    try {
      return new MediaRecorderConstructor(stream, { mimeType });
    } catch (error) {
      console.warn('Voice recorder MIME type was rejected; using browser default recorder.', error);
    }
  }

  return new MediaRecorderConstructor(stream);
};

const getVoiceRecordingErrorMessage = (error) => {
  const errorName = String(error?.name || '').trim().toLowerCase();

  if (errorName === 'notallowederror' || errorName === 'permissiondeniederror' || errorName === 'securityerror') {
    return 'Microphone access is required to record audio.';
  }

  if (errorName === 'notfounderror' || errorName === 'devicesnotfounderror') {
    return 'No microphone was found. Please connect a microphone and try again.';
  }

  if (errorName === 'notreadableerror' || errorName === 'trackstarterror') {
    return 'Your microphone is already in use or unavailable right now.';
  }

  if (errorName === 'overconstrainederror' || errorName === 'constraintnotfounderror') {
    return 'This microphone could not be used for voice recording.';
  }

  if (errorName === 'notsupportederror') {
    return 'Voice recording is not supported in this browser.';
  }

  return 'Voice recording could not be started. Please try again.';
};

const getVoiceRecordingExtension = (mimeType = '') => {
  if (mimeType.includes('ogg')) return 'ogg';
  if (mimeType.includes('mp4')) return 'm4a';
  return 'webm';
};

const getFileExtension = (fileName = '') =>
  String(fileName || '').trim().split('.').pop()?.toLowerCase() || '';

const CHAT_MEDIA_VIDEO_UPLOAD_MIME_TYPES = new Set(['video/mp4', 'video/mpeg']);
const CHAT_MEDIA_VIDEO_UPLOAD_MIME_TYPE_BY_EXTENSION = Object.freeze({
  mp4: 'video/mp4',
  m4v: 'video/mp4',
  mpeg: 'video/mpeg',
  mpg: 'video/mpeg',
});

const getChatMediaVideoUploadMimeType = (file = {}) => {
  const extension = getFileExtension(file?.name);
  const extensionMimeType = CHAT_MEDIA_VIDEO_UPLOAD_MIME_TYPE_BY_EXTENSION[extension] || '';
  if (extensionMimeType) return extensionMimeType;

  const providedMimeType = String(file?.type || '').trim().toLowerCase();
  if (CHAT_MEDIA_VIDEO_UPLOAD_MIME_TYPES.has(providedMimeType)) {
    return providedMimeType;
  }

  const resolvedMimeType = resolveVideoMimeType({
    mimeType: providedMimeType,
    fileName: file?.name,
  });
  return CHAT_MEDIA_VIDEO_UPLOAD_MIME_TYPES.has(resolvedMimeType) ? resolvedMimeType : '';
};

const isChatMediaVideoUploadSupported = (file = {}) =>
  Boolean(getChatMediaVideoUploadMimeType(file));

const normalizeVideoAttachmentFile = (file) => {
  if (!file) return file;

  const resolvedMimeType = getChatMediaVideoUploadMimeType(file);
  if (!resolvedMimeType || file.type === resolvedMimeType) {
    return file;
  }

  try {
    return new File([file], file.name || 'video.mp4', {
      type: resolvedMimeType,
      lastModified: file.lastModified || Date.now(),
    });
  } catch {
    return file;
  }
};

const normalizeVideoMediaItemForUpload = (mediaItem = {}) => {
  if (mediaItem?.type !== 'video' || !mediaItem?.file) return mediaItem;

  const normalizedFile = normalizeVideoAttachmentFile(mediaItem.file);
  const normalizedMimeType =
    getChatMediaVideoUploadMimeType(normalizedFile) ||
    getChatMediaVideoUploadMimeType(mediaItem.file) ||
    mediaItem.mimeType ||
    normalizedFile?.type ||
    '';

  return {
    ...mediaItem,
    file: normalizedFile,
    name: mediaItem.name || normalizedFile?.name || '',
    size: Number(normalizedFile?.size || mediaItem.size || 0),
    mimeType: normalizedMimeType,
  };
};

const limitGroupNameDraftValue = (value = '') =>
  Array.from(String(value || '')).slice(0, GROUP_NAME_MAX_LENGTH).join('');

const getImageAttachmentMimeType = (file = {}) => {
  const extension = getFileExtension(file?.name);
  const inferredMimeType = IMAGE_ATTACHMENT_MIME_TYPES_BY_EXTENSION[extension] || '';
  const providedMimeType = String(file?.type || '').toLowerCase();
  if (inferredMimeType && (!providedMimeType || providedMimeType === 'application/octet-stream')) {
    return inferredMimeType;
  }

  return providedMimeType || inferredMimeType;
};

const normalizeImageAttachmentFile = (file) => {
  if (!file) return file;

  const resolvedMimeType = getImageAttachmentMimeType(file);
  if (!resolvedMimeType || file.type === resolvedMimeType) {
    return file;
  }

  try {
    return new File([file], file.name || 'image', {
      type: resolvedMimeType,
      lastModified: file.lastModified || Date.now(),
    });
  } catch {
    return file;
  }
};

const getClipboardImageFile = (clipboardData) => {
  const clipboardItems = Array.from(clipboardData?.items || []);
  const imageItem = clipboardItems.find((item) =>
    item?.kind === 'file' && String(item?.type || '').toLowerCase().startsWith('image/')
  );
  const itemFile = imageItem?.getAsFile?.() || null;
  if (itemFile && String(itemFile.type || imageItem?.type || '').toLowerCase().startsWith('image/')) {
    return itemFile;
  }

  return Array.from(clipboardData?.files || []).find((file) =>
    String(file?.type || '').toLowerCase().startsWith('image/')
  ) || null;
};

const getAudioAttachmentMimeType = (file = {}) => {
  const extension = getFileExtension(file?.name);
  const inferredMimeType = AUDIO_ATTACHMENT_MIME_TYPES_BY_EXTENSION[extension] || '';
  const providedMimeType = String(file?.type || '').toLowerCase();
  if (inferredMimeType && (!providedMimeType || providedMimeType === 'application/octet-stream')) {
    return inferredMimeType;
  }

  return providedMimeType || inferredMimeType;
};

const getDocumentAttachmentMimeType = (file = {}) => {
  const extension = getFileExtension(file?.name);
  const inferredMimeType = DOCUMENT_ATTACHMENT_MIME_TYPES_BY_EXTENSION[extension] || '';
  const providedMimeType = String(file?.type || '').toLowerCase();
  // Browser and Windows MIME detection is inconsistent for Office documents,
  // so a recognized filename extension is the authoritative value here.
  if (inferredMimeType) {
    return inferredMimeType;
  }

  return providedMimeType || inferredMimeType;
};

const isMediaDocumentAttachmentFile = (file = {}) => {
  const fileName = String(file?.name || '').trim();
  const extension = getFileExtension(fileName);
  const mimeType = String(file?.type || '').toLowerCase();

  return (
    mimeType.startsWith('image/') ||
    mimeType.startsWith('video/') ||
    IMAGE_ATTACHMENT_EXTENSIONS.has(extension) ||
    isSupportedVideoExtension(fileName)
  );
};

const createStorageSafeFileName = (fileName = 'attachment') => {
  const normalizedName = String(fileName || '').trim() || 'attachment';
  const safeName = normalizedName
    .replace(/[^a-z0-9._-]+/gi, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 140);

  return safeName || 'attachment';
};

const getMediaDocumentStorageExtension = (file = {}) => {
  const extension = getFileExtension(file?.name);
  if (extension) return extension;

  return MEDIA_DOCUMENT_ATTACHMENT_EXTENSION_BY_MIME_TYPE[
    String(file?.type || '').toLowerCase()
  ] || 'bin';
};

const createMediaDocumentStoragePath = ({ file, userId, messageId } = {}) => {
  const safeUserId = String(userId || 'user').replace(/[^a-z0-9_-]/gi, '-');
  const safeMessageId = String(messageId || Date.now()).replace(/[^a-z0-9_-]/gi, '-');
  const extension = getMediaDocumentStorageExtension(file);
  const safeName = createStorageSafeFileName(file?.name || `document.${extension}`);
  const fileNameWithExtension = /\.[a-z0-9]{1,12}$/i.test(safeName)
    ? safeName
    : `${safeName}.${extension}`;

  return `documents/${safeUserId}/${Date.now()}-${safeMessageId}-${fileNameWithExtension}`;
};

const normalizeAudioAttachmentFile = (file) => {
  if (!file) return file;

  const resolvedMimeType = getAudioAttachmentMimeType(file);
  if (!resolvedMimeType || file.type === resolvedMimeType) {
    return file;
  }

  try {
    return new File([file], file.name || 'audio', {
      type: resolvedMimeType,
      lastModified: file.lastModified || Date.now(),
    });
  } catch {
    return file;
  }
};

