const ChatMessageStatusIcon = ({ status }) => {
  const normalizedStatus = normalizeMessageStatus(status, 'sent');
  const strokeColor = normalizedStatus === 'read' ? '#60A5FA' : '#94A3B8';
  if (normalizedStatus === 'failed') return null;
  if (normalizedStatus === 'pending' || normalizedStatus === 'sending') {
    return (
      <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <circle cx="9" cy="9" r="5.75" stroke={strokeColor} strokeWidth="1.5" />
        <path d="M9 5.5V9L11.6 10.7" stroke={strokeColor} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  if (normalizedStatus === 'sent') {
    return (
      <svg width="22" height="20" viewBox="0 0 22 20" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <path d="M6 10L10 14L16.5 7.5" stroke={strokeColor} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  return (
    <svg width="22" height="20" viewBox="0 0 22 20" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <path d="M2 10L6 14L12.5 7.5" stroke={strokeColor} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M9 10L13 14L19.5 7.5" stroke={strokeColor} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
};

const resolveDeletedMessageDisplayText = ({ message = {} } = {}) => {
  const explicitText = String(message?.deletedDisplayText || '').trim();
  if (explicitText) {
    return explicitText;
  }

  return 'This message has been deleted!';
};

const SidebarMessageStatusIcon = ({ status }) => {
  const normalizedStatus = normalizeMessageStatus(status, 'sent');
  const strokeColor = normalizedStatus === 'read' ? '#60A5FA' : '#94A3B8';
  if (normalizedStatus === 'failed') return null;
  if (normalizedStatus === 'pending' || normalizedStatus === 'sending') {
    return (
      <svg width="14" height="14" viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <path d="M3 7H10.5" stroke="#94A3B8" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M8 4.5L10.5 7L8 9.5" stroke="#94A3B8" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  if (normalizedStatus === 'sent') {
    return (
      <svg width="18" height="10" viewBox="0 0 18 10" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <path d="M5 5L8.5 8.5L14.5 2.5" stroke={strokeColor} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  return (
    <svg width="18" height="10" viewBox="0 0 18 10" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <path d="M1 5L4.5 8.5L10.5 2.5" stroke={strokeColor} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M7 5L10.5 8.5L16.5 2.5" stroke={strokeColor} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
};

const PresenceBadge = ({ kind = 'offline', className = '' }) => {
  // Losing this device's connection says nothing about a contact's presence.
  // The network banner reports it once, instead of an arrow on every contact
  // and group avatar (BUG_USR_334).
  if (kind === 'no-internet') return null;

  const paletteByKind = {
    online: 'bg-[#10B981]',
    offline: 'bg-[#94A3B8]',
  };
  return (
    <span
      className={`pointer-events-none absolute bottom-0 right-0 flex h-4 w-4 items-center justify-center rounded-full border-2 border-white shadow-sm ${paletteByKind[kind] || paletteByKind.offline} ${className}`}
      aria-hidden="true"
    >
      {kind === 'online' ? (
        <svg width="8" height="8" viewBox="0 0 8 8" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M1.25 4.1L3.1 5.95L6.75 2.25" stroke="white" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      ) : null}
      {kind === 'offline' ? (
        <svg width="8" height="8" viewBox="0 0 8 8" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M2.2 2.2L5.8 5.8" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
          <path d="M5.8 2.2L2.2 5.8" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      ) : null}
    </span>
  );
};

const GroupDefaultAvatarIcon = ({ className = 'h-7 w-7' }) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.8"
    strokeLinecap="round"
    strokeLinejoin="round"
    className={className}
    aria-hidden="true"
  >
    <circle cx="9" cy="8" r="3" />
    <path d="M3.5 19v-1.5A4.5 4.5 0 0 1 8 13h2a4.5 4.5 0 0 1 4.5 4.5V19" />
    <path d="M15 5.5a3 3 0 0 1 0 5.8M17 14a4.5 4.5 0 0 1 3.5 4.4V19" />
  </svg>
);

const resolveGroupProfilePicture = (contact = {}) => {
  const customGroupPicture = [
    contact?.groupPhoto,
    contact?.broadcastPhoto,
    contact?.profilePic,
    contact?.profileImage,
    contact?.profilePicture,
    contact?.photo,
    contact?.photoURL,
    contact?.avatar,
    contact?.avatarUrl,
    contact?.image,
  ].find((picture) => isCustomProfilePictureValue(picture));

  return customGroupPicture ? normalizeProfilePictureValue(customGroupPicture) : '';
};

const ContactAvatar = ({
  contact,
  presence,
  sizeClass = 'h-12 w-12',
  textClassName = 'text-base',
  showPresence = true,
}) => {
  const isGroupContact = isGroupThreadContact(contact);
  const resolvedProfilePic = isGroupContact
    ? resolveGroupProfilePicture(contact)
    : resolveContactProfilePicture(contact);

  return (
    <div className={`relative ${sizeClass} flex-shrink-0`} title={isGroupContact ? contact?.name || 'Group' : presence?.label || contact?.name || 'Contact'}>
      <div className={`relative flex h-full w-full items-center justify-center overflow-hidden rounded-full border-2 border-white bg-purple-100 font-bold text-[#9b66ff] shadow-sm ${textClassName}`}>
        {isGroupContact ? <GroupDefaultAvatarIcon /> : null}
        {resolvedProfilePic ? (
          <img
            src={resolvedProfilePic}
            className="absolute inset-0 h-full w-full object-cover"
            alt={contact?.name || (isGroupContact ? 'Group' : 'Default profile')}
            onError={(event) => {
              if (isGroupContact) event.currentTarget.style.display = 'none';
              else event.currentTarget.src = defaultProfilePic;
            }}
          />
        ) : !isGroupContact ? (
          <img src={defaultProfilePic} className="h-full w-full object-cover" alt={contact?.name || 'Default profile'} />
        ) : null}
      </div>
      {showPresence && !isGroupContact && presence ? <PresenceBadge kind={presence.kind} /> : null}
    </div>
  );
};

const CHAT_MODULES = {
  chats: 'chats',
  groups: 'groups',
  broadcasts: 'broadcasts',
};
const BROADCAST_NAME_MAX_LENGTH = 25;
const BROADCAST_PHOTO_MAX_BYTES = 5 * 1024 * 1024;
const BROADCAST_IMAGE_ATTACHMENT_MAX_BYTES = BROADCAST_PHOTO_MAX_BYTES;
const GROUP_NAME_MAX_LENGTH = 50;
const GROUP_DESCRIPTION_MAX_LENGTH = 100;
const GROUP_RULES_MIN_LENGTH = 100;
const GROUP_RULES_MAX_LENGTH = 150;
const CONTACT_BLOCK_STATE_NOTIFICATION_KIND = 'contact-block-state';
const CONTACT_BLOCK_NOTIFICATION_ACTION = 'contact_blocked';
const CONTACT_UNBLOCK_NOTIFICATION_ACTION = 'contact_unblocked';
const CONTACT_BLOCK_NOTIFICATION_MARKER = '**CHATTERLY_CONTACT_BLOCK_STATE**';
const GROUP_BLOCK_NOTIFICATION_KIND = 'group-blocked';
const GROUP_UNBLOCK_NOTIFICATION_KIND = 'group-unblocked';
const GROUP_BLOCK_NOTIFICATION_MARKER = '**CHATTERLY_GROUP_BLOCKED**';
const GROUP_UNBLOCK_NOTIFICATION_MARKER = '**CHATTERLY_GROUP_UNBLOCKED**';
const GROUP_MEMBERSHIP_NOTIFICATION_MARKER = '**CHATTERLY_GROUP_MEMBERSHIP**';
const GROUP_BLOCK_NOTIFICATION_MARKERS = Object.freeze([
  GROUP_BLOCK_NOTIFICATION_MARKER,
  '__CHATTERLY_GROUP_BLOCKED__',
]);
const GROUP_UNBLOCK_NOTIFICATION_MARKERS = Object.freeze([
  GROUP_UNBLOCK_NOTIFICATION_MARKER,
  '__CHATTERLY_GROUP_UNBLOCKED__',
]);

const normalizeChatModule = (value) =>
  value === CHAT_MODULES.groups || value === CHAT_MODULES.broadcasts
    ? value
    : CHAT_MODULES.chats;

const isBroadcastThreadContact = (contact = {}) =>
  Boolean(contact?.isBroadcast || contact?.type === 'broadcast' || contact?.chatType === 'broadcast');

const isGroupThreadContact = (contact = {}) =>
  Boolean(contact?.isGroup || contact?.type === 'group' || contact?.chatType === 'group') ||
  isBroadcastThreadContact(contact);

const getChatModuleRootRoute = (moduleName = CHAT_MODULES.chats) =>
  normalizeChatModule(moduleName) === CHAT_MODULES.groups
    ? '/groups'
    : normalizeChatModule(moduleName) === CHAT_MODULES.broadcasts
      ? '/broadcasts'
      : '/chats';

const getGroupThreadChatId = (group = {}) =>
  String(group?.chatId || group?.broadcastId || group?.groupId || group?.id || group?._id || '').trim();

const isBackendObjectId = (value = '') => /^[a-f\d]{24}$/i.test(String(value || '').trim());

const getMessageGroupCallId = (message = {}) =>
  String(
    message?.groupCallId ||
      message?.metadata?.groupCallId ||
      message?.callId?._id ||
      message?.callId?.id ||
      message?.callId ||
      message?.metadata?.callId?._id ||
      message?.metadata?.callId?.id ||
      message?.metadata?.callId ||
      ''
  ).trim();

const getMessageCallStatus = (message = {}) =>
  String(message?.callStatus || message?.metadata?.callStatus || '').trim().toLowerCase();

const getMessageCallText = (message = {}) =>
  String(
    message?.content ||
      message?.message ||
      message?.text ||
      message?.encryptedContent ||
      message?.metadata?.content ||
      message?.metadata?.message ||
      message?.metadata?.text ||
      ''
  ).trim();

const isGroupCallLogNotificationMessage = (message = {}) => {
  const messageType = String(
    message?.messageType || message?.metadata?.messageType || message?.metadata?.type || message?.type || ''
  ).trim().toLowerCase();
  const callStatus = getMessageCallStatus(message);
  const callText = getMessageCallText(message).toLowerCase();
  const isRecognizedCallLogText = /^(?:(?:outgoing|incoming)\s+)?(?:missed\s+)?(?:audio|video|voice)\s+(?:group\s+)?call\b(?:\s*(?:[-:\u2022\u00b7\u2013\u2014]\s*)?(?:answered|completed|rejected|declined|cancelled|canceled|not answered|missed|ended|started))?(?:\s*\(\s*(?:\d+\s*s|(?:\d+:)?\d{1,2}:\d{2})\s*\))?$/i.test(callText);

  return Boolean(
    getMessageGroupCallId(message) ||
      messageType === 'call' ||
      ['started', 'ended', 'completed', 'rejected', 'cancelled', 'canceled', 'missed', 'not_answered'].includes(callStatus) ||
      isRecognizedCallLogText
  );
};

const getMessageTimestampValue = (message = {}) => {
  const timestamp = new Date(
    message?.createdAt || message?.timestamp || message?.sentAt || message?.time || 0
  ).getTime();
  return Number.isFinite(timestamp) ? timestamp : 0;
};

const getLatestGroupCallStatusFromMessages = (messages = [], groupCallId = '') => {
  const normalizedGroupCallId = String(groupCallId || '').trim();
  if (!normalizedGroupCallId) return '';

  const latestCallMessage = (Array.isArray(messages) ? messages : [])
    .map((message, index) => ({
      index,
      message,
      timestampValue: getMessageTimestampValue(message),
    }))
    .filter(({ message }) =>
      getMessageGroupCallId(message) === normalizedGroupCallId &&
      ['started', 'ended', 'completed', 'not_answered'].includes(getMessageCallStatus(message))
    )
    .sort((firstMessage, secondMessage) =>
      secondMessage.timestampValue - firstMessage.timestampValue ||
      secondMessage.index - firstMessage.index
    )[0]?.message;

  return getMessageCallStatus(latestCallMessage);
};

const getActiveGroupCallFromMessages = (messages = [], groupId = '') => {
  const callStates = new Map();

  (Array.isArray(messages) ? messages : []).forEach((message, index) => {
    const groupCallId = getMessageGroupCallId(message);
    const callStatus = getMessageCallStatus(message);
    if (!groupCallId || !['started', 'ended', 'completed', 'not_answered'].includes(callStatus)) {
      return;
    }

    const timestampValue = getMessageTimestampValue(message);
    const currentState = callStates.get(groupCallId);
    if (
      currentState &&
      (currentState.timestampValue > timestampValue ||
        (currentState.timestampValue === timestampValue && currentState.index > index))
    ) {
      return;
    }

    callStates.set(groupCallId, {
      status: callStatus,
      message,
      index,
      timestampValue,
    });
  });

  return Array.from(callStates.entries())
    .filter(([, callState]) => callState.status === 'started')
    .sort(([, firstCall], [, secondCall]) =>
      secondCall.timestampValue - firstCall.timestampValue ||
      secondCall.index - firstCall.index
    )
    .map(([groupCallId, callState]) => {
      const message = callState.message;
      const content = String(message?.content || message?.text || message?.message || '');
      const callType = /\baudio\b|\bvoice\b/i.test(content) ? CALL_TYPE.AUDIO : CALL_TYPE.VIDEO;
      return {
        groupCallId,
        callId: groupCallId,
        groupId: String(message?.groupId || message?.chatId || groupId || '').trim(),
        startedBy: String(message?.senderId || message?.sender?._id || message?.sender?.id || '').trim(),
        startedAt:
          message?.createdAt ||
          message?.timestamp ||
          message?.sentAt ||
          new Date(callState.timestampValue || Date.now()).toISOString(),
        type: callType,
        callType,
      };
    })[0] || null;
};

const getGroupThreadName = (group = {}) =>
  String(group?.groupName || group?.broadcastName || group?.name || '').trim();

const getGroupChatIdFromRouteValue = (value = '') => {
  const normalizedValue = String(value || '').trim();
  if (!normalizedValue) return '';

  const match = normalizedValue.match(/\/groups\/chat\/([^/?#]+)/i);
  return match?.[1] ? decodeURIComponent(match[1]) : '';
};

const buildGroupBlockNotificationText = ({ blockerName = 'A member', groupName = 'this group' } = {}) =>
  `${String(blockerName || 'A member').trim() || 'A member'} blocked the group ${String(groupName || 'this group').trim() || 'this group'}.`;

const buildGroupUnblockNotificationText = ({ blockerName = 'A member', groupName = 'this group' } = {}) =>
  `${String(blockerName || 'A member').trim() || 'A member'} unblocked the group ${String(groupName || 'this group').trim() || 'this group'}.`;

const buildGroupBlockNotificationContent = ({
  groupId = '',
  groupName = '',
  blockerId = '',
  blockerName = '',
} = {}) =>
  `${GROUP_BLOCK_NOTIFICATION_MARKER}${JSON.stringify({
    groupId: String(groupId || '').trim(),
    groupName: String(groupName || '').trim(),
    blockerId: String(blockerId || '').trim(),
    blockerName: String(blockerName || '').trim(),
  })}`;

const buildGroupUnblockNotificationContent = ({
  groupId = '',
  groupName = '',
  blockerId = '',
  blockerName = '',
} = {}) =>
  `${GROUP_UNBLOCK_NOTIFICATION_MARKER}${JSON.stringify({
    groupId: String(groupId || '').trim(),
    groupName: String(groupName || '').trim(),
    blockerId: String(blockerId || '').trim(),
    blockerName: String(blockerName || '').trim(),
  })}`;

const buildGroupMembershipNotificationContent = ({
  action = 'added',
  participantNames = [],
  actorName = '',
} = {}) => {
  const normalizedParticipantNames = (Array.isArray(participantNames) ? participantNames : [])
    .map((participantName) => String(participantName || '').trim())
    .filter(Boolean);
  const participantLabel =
    normalizedParticipantNames.length === 1
      ? normalizedParticipantNames[0]
      : normalizedParticipantNames.length === 2
        ? `${normalizedParticipantNames[0]} and ${normalizedParticipantNames[1]}`
        : normalizedParticipantNames.length > 2
          ? `${normalizedParticipantNames.slice(0, -1).join(', ')}, and ${normalizedParticipantNames[normalizedParticipantNames.length - 1]}`
          : 'a participant';
  const normalizedActorName = String(actorName || '').trim() || 'A group admin';
  const normalizedAction = action === 'removed' ? 'removed' : 'added';

  return `${normalizedActorName} ${normalizedAction} ${participantLabel}.`;
};

const parseGroupMembershipNotificationContent = (value = '') => {
  const normalizedValue = String(value || '').trim();
  const markerIndex = normalizedValue.indexOf(GROUP_MEMBERSHIP_NOTIFICATION_MARKER);
  if (markerIndex < 0) return null;

  try {
    const payload = JSON.parse(
      normalizedValue.slice(markerIndex + GROUP_MEMBERSHIP_NOTIFICATION_MARKER.length).trim()
    ) || {};
    const participantIds = (Array.isArray(payload.participantIds) ? payload.participantIds : [])
      .map((participantId) => String(participantId || '').trim())
      .filter(Boolean);
    const participantNames = (Array.isArray(payload.participantNames) ? payload.participantNames : [])
      .map((participantName) => String(participantName || '').trim())
      .filter(Boolean);

    if (!participantIds.length && !participantNames.length) return null;

    return {
      action: payload.action === 'removed' ? 'removed' : 'added',
      groupId: String(payload.groupId || '').trim(),
      participantIds,
      participantNames,
      actorName: String(payload.actorName || '').trim(),
    };
  } catch {
    return null;
  }
};

const getGroupMembershipNotificationEventForMessage = (message = {}, fallback = {}) => {
  const contentCandidates = [
    message?.content,
    message?.message,
    message?.text,
    message?.body,
  ]
    .filter((value) => value !== undefined && value !== null)
    .map((value) => String(value).trim())
    .filter(Boolean);
  const legacyMembershipEvent = contentCandidates
    .map((value) => parseGroupMembershipNotificationContent(value))
    .find(Boolean);
  const clientMessageId = String(
    message?.tempId ||
      message?.clientMessageId ||
      message?.localId ||
      message?.id ||
      message?._id ||
      ''
  ).trim();
  const readableActionMatch = clientMessageId.match(/group-membership-(added|removed)/i);
  const readableText = contentCandidates.find((value) =>
    /\s(?:added|removed)\s/i.test(value)
  ) || '';
  const readableTextMatch = readableText.match(/^(.+?)\s+(added|removed)\s+(.+?)\.?$/i);
  const readableMembershipEvent =
    readableActionMatch && readableTextMatch
      ? {
          action: readableActionMatch[1].toLowerCase() === 'removed' ? 'removed' : 'added',
          groupId: '',
          participantIds: [],
          participantNames: [String(readableTextMatch[3] || '').replace(/\.$/, '').trim()].filter(Boolean),
          actorName: String(readableTextMatch[1] || '').trim(),
        }
      : null;
  const membershipEvent = legacyMembershipEvent || readableMembershipEvent;
  if (!membershipEvent) return null;

  const chatId = String(
    membershipEvent.groupId ||
      message?.groupId ||
      message?.chatId ||
      fallback?.chatId ||
      ''
  ).trim();
  if (!chatId) return null;

  return {
    ...membershipEvent,
    chatId,
    id: String(message?.id || message?._id || message?.messageId || message?.tempId || '').trim(),
    createdAt: message?.timestamp || message?.createdAt || fallback?.createdAt || new Date().toISOString(),
  };
};

const isGroupMembershipNotificationMessage = (message = {}, fallback = {}) =>
  Boolean(getGroupMembershipNotificationEventForMessage(message, fallback));

const buildGroupMembershipTimelineNotice = (message = {}, fallback = {}) => {
  const membershipEvent = getGroupMembershipNotificationEventForMessage(message, fallback);
  if (!membershipEvent) return null;

  const participantNames = membershipEvent.participantNames.length
    ? membershipEvent.participantNames
    : membershipEvent.participantIds.map(() => 'a participant');
  const participantLabel =
    participantNames.length === 1
      ? participantNames[0]
      : participantNames.length === 2
        ? `${participantNames[0]} and ${participantNames[1]}`
        : `${participantNames.slice(0, -1).join(', ')}, and ${participantNames[participantNames.length - 1]}`;
  const text = `${membershipEvent.actorName || 'A group admin'} ${membershipEvent.action} ${participantLabel}.`;
  const membershipParticipantKey = membershipEvent.participantIds.length
    ? membershipEvent.participantIds.slice().sort().join('|')
    : membershipEvent.participantNames.slice().sort().join('|');

  return {
    id: membershipEvent.id
      ? `group-membership-notice-${membershipEvent.id}`
      : createMessageId('group-membership-notice'),
    chatId: membershipEvent.chatId,
    text,
    createdAt: membershipEvent.createdAt,
    membershipAction: membershipEvent.action,
    membershipParticipantKey,
  };
};

const getGroupRoleChangeNotificationEventForMessage = (message = {}, fallback = {}) => {
  const text = [message?.content, message?.message, message?.text, message?.body]
    .map((value) => String(value || '').trim())
    .find((value) => /^.+?\s+(?:was|has been)\s+(?:promoted to|demoted to|removed as|changed to)\s+(?:admin|moderator|member)\.?$/i.test(value));
  if (!text) return null;

  const chatId = String(message?.groupId || message?.chatId || fallback?.chatId || '').trim();
  if (!chatId) return null;

  return {
    id: String(message?.id || message?._id || message?.messageId || message?.tempId || '').trim(),
    chatId,
    text,
    createdAt: message?.timestamp || message?.createdAt || fallback?.createdAt || new Date().toISOString(),
  };
};

const isGroupRoleChangeNotificationMessage = (message = {}, fallback = {}) =>
  Boolean(getGroupRoleChangeNotificationEventForMessage(message, fallback));

const resolveGroupRoleChangeActorName = (message = {}, fallback = {}) => {
  const sender = message?.sender && typeof message.sender === 'object' ? message.sender : {};
  const senderId = String(
    message?.senderId ||
      sender?._id ||
      sender?.id ||
      sender?.userId ||
      (typeof message?.sender === 'string' ? message.sender : '') ||
      ''
  ).trim();
  const isUsableName = (value) => {
    const name = String(value || '').trim();
    return name && !/^(?:you|member|group member|unknown user)$/i.test(name) && !/^[a-f\d]{24}$/i.test(name);
  };
  const directName = [sender?.name, sender?.fullName, message?.senderName].find(isUsableName);
  if (directName) return String(directName).trim();
  if (!senderId) return '';

  if (doGroupMemberIdsMatch(senderId, fallback?.currentUserId) && isUsableName(fallback?.currentUserName)) {
    return String(fallback.currentUserName).trim();
  }

  const groupMember = (fallback?.groupMembers || []).find((member) =>
    [getGroupMemberId(member), member?.userId, member?.id, member?.user?._id].some((memberId) =>
      doGroupMemberIdsMatch(memberId, senderId)
    )
  );
  const profile = fallback?.groupMemberProfilesById?.[senderId];
  const savedContact = (fallback?.contacts || []).find((contact) =>
    doesContactMatchGroupMemberId(contact, senderId)
  );
  const matchedName = [
    groupMember?.name,
    groupMember?.user?.name,
    profile?.name,
    profile?.fullName,
    savedContact?.name,
    savedContact?.fullName,
  ].find(isUsableName);
  return matchedName ? String(matchedName).trim() : '';
};

const buildGroupRoleChangeTimelineNotice = (message = {}, fallback = {}) => {
  const roleChangeEvent = getGroupRoleChangeNotificationEventForMessage(message, fallback);
  if (!roleChangeEvent) return null;

  const actorName = resolveGroupRoleChangeActorName(message, fallback);
  const roleChangeMatch = roleChangeEvent.text.match(
    /^(.+?)\s+(?:was|has been)\s+(promoted to|demoted to|removed as|changed to)\s+(admin|moderator|member)\.?$/i
  );
  const targetName = roleChangeMatch?.[1];
  const action = roleChangeMatch?.[2]?.toLowerCase();
  const role = roleChangeMatch?.[3];
  const text = actorName && targetName && role
    ? action === 'promoted to'
      ? `${actorName} promoted ${targetName} to ${role}.`
      : action === 'demoted to'
        ? `${actorName} demoted ${targetName} to ${role}.`
        : action === 'removed as'
          ? `${actorName} demoted ${targetName} from ${role}.`
          : `${actorName} changed ${targetName}'s role to ${role}.`
    : roleChangeEvent.text;

  return {
    id: roleChangeEvent.id ? `group-role-change-notice-${roleChangeEvent.id}` : createMessageId('group-role-change-notice'),
    chatId: roleChangeEvent.chatId,
    text,
    createdAt: roleChangeEvent.createdAt,
    kind: 'group-role-change',
    noticeKey: `group-role-change|${roleChangeEvent.id || roleChangeEvent.text}`,
  };
};

const parseGroupBlockStateNotificationContent = (value = '') => {
  const normalizedValue = String(value || '').trim();
  const blockMarker = GROUP_BLOCK_NOTIFICATION_MARKERS.find((marker) =>
    normalizedValue.startsWith(marker)
  );
  const unblockMarker = GROUP_UNBLOCK_NOTIFICATION_MARKERS.find((marker) =>
    normalizedValue.startsWith(marker)
  );
  const marker = blockMarker || unblockMarker;
  if (!marker) return null;

  try {
    return {
      action: unblockMarker ? 'unblock' : 'block',
      ...(JSON.parse(normalizedValue.slice(marker.length)) || {}),
    };
  } catch {
    return { action: unblockMarker ? 'unblock' : 'block' };
  }
};

const resolveGroupBlockStateNotificationEvent = (payload = {}, fallback = {}) => {
  const metadata = payload?.metadata || {};
  const rawText = String(
    payload?.content ||
      payload?.message ||
      payload?.text ||
      payload?.body ||
      payload?.caption ||
      ''
  ).trim();
  const markerPayload = parseGroupBlockStateNotificationContent(rawText);
  const normalizedKind = String(
    payload?.kind ||
      payload?.action ||
      metadata?.kind ||
      metadata?.action ||
      ''
  ).trim().toLowerCase();
  const isUnblockKind =
    normalizedKind === GROUP_UNBLOCK_NOTIFICATION_KIND ||
    normalizedKind === 'group_unblocked' ||
    normalizedKind === 'unblock-group' ||
    normalizedKind === 'group-unblock';
  const isBlockKind =
    normalizedKind === GROUP_BLOCK_NOTIFICATION_KIND ||
    normalizedKind === 'group_blocked' ||
    normalizedKind === 'block-group' ||
    normalizedKind === 'group-block';
  const routeGroupId = getGroupChatIdFromRouteValue(
    payload?.targetUrl ||
      payload?.redir ||
      payload?.redirect ||
      payload?.click_action ||
      payload?.link ||
      ''
  );
  const fallbackGroupId = String(fallback?.chatId || fallback?.groupId || '').trim();
  const isReadableGroupBlockStateText =
    Boolean(routeGroupId || fallbackGroupId) &&
    (
      /\b(unblocked|blocked)\s+the\s+group\b/i.test(rawText) ||
      /\bgroup\s+(?:has\s+been\s+)?(?:unblocked|blocked)\b/i.test(rawText)
    );
  const isGroupBlockStateEvent =
    Boolean(markerPayload) ||
    isBlockKind ||
    isUnblockKind ||
    isReadableGroupBlockStateText;

  if (!isGroupBlockStateEvent) {
    return null;
  }

  const action =
    markerPayload?.action === 'unblock' ||
    isUnblockKind ||
    /\bunblocked\b/i.test(rawText)
      ? 'unblock'
      : 'block';

  const groupId = String(
    markerPayload?.groupId ||
      payload?.groupId ||
      payload?.chatId ||
      metadata?.groupId ||
      routeGroupId ||
      fallbackGroupId ||
      fallback?.chatId ||
      ''
  ).trim();

  if (!groupId) {
    return null;
  }

  const groupName = String(
    markerPayload?.groupName ||
      payload?.groupName ||
      metadata?.groupName ||
      fallback?.groupName ||
      'this group'
  ).trim();
  const blockerId = String(
    markerPayload?.blockerId ||
      payload?.senderId ||
      payload?.sender ||
      fallback?.senderId ||
      ''
  ).trim();
  const blockerName = String(
    markerPayload?.blockerName ||
      payload?.senderName ||
      payload?.sender?.name ||
      fallback?.senderName ||
      'A member'
  ).trim();

  return {
    action,
    chatId: groupId,
    groupId,
    groupName,
    blockerId,
    blockerName,
    text:
      action === 'unblock'
        ? buildGroupUnblockNotificationText({ blockerName, groupName })
        : buildGroupBlockNotificationText({ blockerName, groupName }),
    id: String(payload?.id || payload?._id || payload?.messageId || payload?.clientMessageId || payload?.tempId || '').trim(),
    timestamp: payload?.timestamp || payload?.createdAt || fallback?.timestamp || new Date().toISOString(),
  };
};

const getDirectChatIdFromRouteValue = (value = '') => {
  const normalizedValue = String(value || '').trim();
  if (!normalizedValue) return '';

  const match = normalizedValue.match(/\/chat\/([^/?#]+)/i);
  return match?.[1] ? decodeURIComponent(match[1]) : '';
};

const buildContactBlockStateNotificationContent = ({
  action = 'block',
  chatId = '',
  blockerId = '',
  blockerName = '',
  blockedUserId = '',
} = {}) =>
  `${CONTACT_BLOCK_NOTIFICATION_MARKER}${JSON.stringify({
    action: action === 'unblock' ? 'unblock' : 'block',
    chatId: String(chatId || '').trim(),
    blockerId: String(blockerId || '').trim(),
    blockerName: String(blockerName || '').trim(),
    blockedUserId: String(blockedUserId || '').trim(),
  })}`;

const parseContactBlockStateNotificationContent = (value = '') => {
  const normalizedValue = String(value || '').trim();
  if (!normalizedValue.startsWith(CONTACT_BLOCK_NOTIFICATION_MARKER)) {
    return null;
  }

  try {
    const parsedPayload = JSON.parse(normalizedValue.slice(CONTACT_BLOCK_NOTIFICATION_MARKER.length));
    return parsedPayload && typeof parsedPayload === 'object' && !Array.isArray(parsedPayload)
      ? parsedPayload
      : null;
  } catch {
    return {};
  }
};

const resolveContactBlockStateNotificationEvent = (payload = {}, fallback = {}) => {
  const metadata = payload?.metadata || {};
  const rawText = String(
    payload?.content ||
      payload?.message ||
      payload?.text ||
      payload?.body ||
      payload?.caption ||
      ''
  ).trim();
  const markerPayload = parseContactBlockStateNotificationContent(rawText);
  const normalizedKind = String(
    markerPayload?.kind ||
      payload?.kind ||
      metadata?.kind ||
      metadata?.systemNoticeKind ||
      payload?.type ||
      ''
  ).trim().toLowerCase();
  const normalizedAction = String(
    markerPayload?.action ||
      payload?.action ||
      metadata?.action ||
      ''
  ).trim().toLowerCase();
  const isContactBlockKind =
    normalizedKind === CONTACT_BLOCK_STATE_NOTIFICATION_KIND ||
    normalizedKind === 'contact_block_state' ||
    normalizedKind === 'direct-block-state' ||
    normalizedKind === 'user-block-state';
  const isBlockAction = [
    CONTACT_BLOCK_NOTIFICATION_ACTION,
    'block',
    'blocked',
    'user_blocked',
    'contact-blocked',
  ].includes(normalizedAction);
  const isUnblockAction = [
    CONTACT_UNBLOCK_NOTIFICATION_ACTION,
    'unblock',
    'unblocked',
    'user_unblocked',
    'contact-unblocked',
  ].includes(normalizedAction);

  if (!markerPayload && !isContactBlockKind && !isBlockAction && !isUnblockAction) {
    return null;
  }

  const action = isUnblockAction ? 'unblock' : 'block';
  const routeChatId = getDirectChatIdFromRouteValue(
    payload?.targetUrl ||
      payload?.redir ||
      payload?.redirect ||
      payload?.click_action ||
      payload?.link ||
      ''
  );
  const chatId = String(
    markerPayload?.chatId ||
      payload?.chatId ||
      metadata?.chatId ||
      payload?.conversationId ||
      payload?.threadId ||
      routeChatId ||
      fallback?.chatId ||
      ''
  ).trim();
  const blockerId = String(
    markerPayload?.blockerId ||
      payload?.blockerId ||
      metadata?.blockerId ||
      payload?.senderId ||
      fallback?.senderId ||
      ''
  ).trim();
  const blockedUserId = String(
    markerPayload?.blockedUserId ||
      payload?.blockedUserId ||
      metadata?.blockedUserId ||
      payload?.receiverId ||
      fallback?.receiverId ||
      ''
  ).trim();

  if (!blockerId && !chatId) {
    return null;
  }

  return {
    action,
    chatId,
    blockerId,
    blockedUserId,
    blockerName: String(
      payload?.blockerName ||
        markerPayload?.blockerName ||
        metadata?.blockerName ||
        payload?.senderName ||
        fallback?.senderName ||
        'Contact'
    ).trim(),
    id: String(payload?.id || payload?._id || payload?.messageId || payload?.clientMessageId || payload?.tempId || '').trim(),
    timestamp: payload?.timestamp || payload?.createdAt || fallback?.timestamp || new Date().toISOString(),
  };
};
const isContactBlockStateNotificationMessage = (message = {}, fallback = {}) =>
  Boolean(resolveContactBlockStateNotificationEvent(message, fallback));

const normalizeGroupBlockStateMessageForDisplay = (message = {}, {
  currentUserId = '',
  chatId = '',
  groupName = '',
  senderId = '',
  senderName = '',
} = {}) => {
  const blockStateEvent = resolveGroupBlockStateNotificationEvent(message, {
    chatId: message?.chatId || message?.groupId || chatId,
    groupName,
    senderId: message?.senderId || senderId,
    senderName: message?.senderName || message?.sender?.name || senderName,
  });

  if (!blockStateEvent) return message;

  return normalizeMessageData({
    ...message,
    id: message?.id || blockStateEvent.id || createMessageId(blockStateEvent.action === 'unblock' ? 'group-unblocked' : 'group-blocked'),
    chatId: blockStateEvent.chatId,
    groupId: blockStateEvent.chatId,
    chatType: 'group',
    type: 'text',
    content: blockStateEvent.text,
    message: blockStateEvent.text,
    text: blockStateEvent.text,
    senderId: blockStateEvent.blockerId || message?.senderId,
    senderName: blockStateEvent.blockerName || message?.senderName,
    timestamp: blockStateEvent.timestamp || message?.timestamp,
    createdAt: blockStateEvent.timestamp || message?.createdAt,
    metadata: {
      ...(message?.metadata || {}),
      kind: blockStateEvent.action === 'unblock'
        ? GROUP_UNBLOCK_NOTIFICATION_KIND
        : GROUP_BLOCK_NOTIFICATION_KIND,
      action: blockStateEvent.action === 'unblock' ? 'group_unblocked' : 'group_blocked',
      groupId: blockStateEvent.chatId,
      groupName: blockStateEvent.groupName,
      blockerId: blockStateEvent.blockerId,
      blockerName: blockStateEvent.blockerName,
      systemNoticeKind: 'group-block-state',
    },
  }, { currentUserId, fallback: message });
};

const getGroupBlockStateNotificationEventForMessage = (message = {}, fallback = {}) =>
  resolveGroupBlockStateNotificationEvent(message, {
    chatId: message?.chatId || message?.groupId || fallback?.chatId,
    groupName: fallback?.groupName,
    senderId: message?.senderId || fallback?.senderId,
    senderName: message?.senderName || message?.sender?.name || fallback?.senderName,
    timestamp: message?.timestamp || message?.createdAt || fallback?.timestamp,
  });

const isGroupBlockStateNotificationMessage = (message = {}, fallback = {}) =>
  Boolean(getGroupBlockStateNotificationEventForMessage(message, fallback));

const buildGroupBlockStateTimelineNotice = (message = {}, fallback = {}) => {
  const blockStateEvent = getGroupBlockStateNotificationEventForMessage(message, fallback);
  if (!blockStateEvent) return null;

  const action = blockStateEvent.action === 'unblock' ? 'unblock' : 'block';
  const createdAt =
    blockStateEvent.timestamp ||
    message?.timestamp ||
    message?.createdAt ||
    new Date().toISOString();
  const baseId = String(blockStateEvent.id || message?.id || message?.messageId || message?.clientMessageId || '').trim();

  return {
    id: baseId
      ? `group-${action}-notice-${baseId}`
      : createMessageId(`group-${action}-notice`),
    chatId: blockStateEvent.chatId,
    text: blockStateEvent.text,
    createdAt,
    groupBlockStateAction: action,
    groupBlockStateKey: [
      action,
      blockStateEvent.chatId,
      blockStateEvent.blockerId,
      new Date(createdAt || 0).getTime() || baseId || blockStateEvent.text,
    ].join('|'),
  };
};

const dedupeChatPinNotices = (notices = []) =>
  (Array.isArray(notices) ? notices : []).reduce((dedupedNotices, notice) => {
    if (!notice || typeof notice !== 'object') return dedupedNotices;

    const normalizedChatId = String(notice?.chatId || '').trim();
    const normalizedText = String(notice?.text || '').trim();
    if (!normalizedChatId || !normalizedText) return dedupedNotices;

    const noticeTime = new Date(notice?.createdAt || 0).getTime();
    const noticeKey = String(
      notice?.noticeKey ||
        notice?.disappearingTimerKey ||
        notice?.groupBlockStateKey ||
        notice?.groupNameChangeKey ||
        `${notice?.membershipAction || ''}|${notice?.membershipParticipantKey || ''}`
    ).trim();

    const hasDuplicate = dedupedNotices.some((existingNotice) => {
      if (String(existingNotice?.chatId || '').trim() !== normalizedChatId) return false;
      if (notice?.id && existingNotice?.id && String(existingNotice.id) === String(notice.id)) return true;

      const existingNoticeKey = String(
        existingNotice?.noticeKey ||
          existingNotice?.disappearingTimerKey ||
          existingNotice?.groupBlockStateKey ||
          existingNotice?.groupNameChangeKey ||
          `${existingNotice?.membershipAction || ''}|${existingNotice?.membershipParticipantKey || ''}`
      ).trim();
      if (noticeKey && existingNoticeKey && noticeKey === existingNoticeKey) return true;

      const isDistinctMessagePinAction = [notice?.kind, existingNotice?.kind].some((kind) =>
        ['message-pinned', 'message-unpinned'].includes(String(kind || '').trim())
      );
      if (isDistinctMessagePinAction) return false;

      const existingNoticeTime = new Date(existingNotice?.createdAt || 0).getTime();
      const isNearbyTime =
        Number.isFinite(noticeTime) &&
        Number.isFinite(existingNoticeTime) &&
        Math.abs(existingNoticeTime - noticeTime) < 30000;

      return isNearbyTime && String(existingNotice?.text || '').trim() === normalizedText;
    });

    return hasDuplicate ? dedupedNotices : [...dedupedNotices, notice];
  }, []);

const getGroupMemberId = (member) => {
  if (member === undefined || member === null) return '';
  if (typeof member === 'string' || typeof member === 'number') return String(member).trim();
  if (typeof member !== 'object') return '';

  return String(
    member?.memberId ||
      member?.member_id ||
      member?.userId ||
      member?.id ||
      member?._id ||
      member?.receiverId ||
      member?.contactId ||
      member?.participantId ||
      member?.phone ||
      ''
  ).trim();
};

const getGroupMemberIds = (group = {}) =>
  Array.isArray(group?.members)
    ? group.members.map((member) => getGroupMemberId(member)).filter(Boolean)
    : [];

const getUniqueGroupMemberIds = (group = {}) =>
  Array.from(new Set(getGroupMemberIds(group).map((memberId) => String(memberId || '').trim()).filter(Boolean)));

// Compact, order-stable fingerprint of a group/broadcast thread's displayed
// state. Used by the route-sync effect to keep the SAME selectedContact object
// when nothing meaningful changed, instead of handing out a fresh
// normalizeGroupThreadContact() result every run (which churned selectedContact's
// identity and drove an infinite re-render loop for group/broadcast threads).
// NOTE: intentionally excludes volatile fields (updatedAt / timestamp /
// lastMessage*) â€” those change constantly (previews, sort keys) and must NOT
// churn the open conversation's identity. Only fields that affect the group's
// displayed header / info are fingerprinted.
const getGroupThreadContactSignature = (group = {}) =>
  [
    getGroupThreadChatId(group),
    getGroupThreadName(group),
    group?.groupPhoto || group?.broadcastPhoto || group?.profilePic || '',
    group?.description || '',
    Number(group?.memberCount || group?.members?.length || 0),
    getUniqueGroupMemberIds(group).slice().sort().join(','),
    (Array.isArray(group?.admins) ? group.admins.map(getGroupMemberId).filter(Boolean).sort().join(',') : ''),
    (Array.isArray(group?.moderators) ? group.moderators.map(getGroupMemberId).filter(Boolean).sort().join(',') : ''),
    group?.hasLeftGroup ? '1' : '0',
    group?.removedFromGroup ? '1' : '0',
  ].join('|');

// Returns the current contact reference when it already represents the same
// thread with an identical signature â€” preventing needless identity changes.
const resolveStableThreadContact = (currentContact, nextContact) =>
  currentContact &&
  getGroupThreadChatId(currentContact) === getGroupThreadChatId(nextContact) &&
  getGroupThreadContactSignature(currentContact) === getGroupThreadContactSignature(nextContact)
    ? currentContact
    : nextContact;

const getNormalizedGroupIdentityText = (value = '') =>
  String(value || '').trim().replace(/\s+/g, ' ').toLowerCase();

const getGroupThreadDedupeKey = (group = {}) => {
  const normalizedName = getNormalizedGroupIdentityText(getGroupThreadName(group));
  const normalizedMemberIds = getUniqueGroupMemberIds(group)
    .map((memberId) => String(memberId || '').trim().toLowerCase())
    .filter(Boolean)
    .sort();

  if (normalizedName && normalizedMemberIds.length) {
    return `signature:${normalizedName}:${normalizedMemberIds.join('|')}`;
  }

  const normalizedChatId = getGroupThreadChatId(group);
  return normalizedChatId ? `id:${normalizedChatId}` : '';
};

const doBroadcastThreadsShareLocalIdentity = (firstBroadcast = {}, secondBroadcast = {}) => {
  const firstChatId = getGroupThreadChatId(firstBroadcast);
  const secondChatId = getGroupThreadChatId(secondBroadcast);

  if (firstChatId && secondChatId && firstChatId === secondChatId) {
    return true;
  }

  const firstDedupeKey = getGroupThreadDedupeKey(firstBroadcast);
  const secondDedupeKey = getGroupThreadDedupeKey(secondBroadcast);
  if (
    firstDedupeKey &&
    secondDedupeKey &&
    firstDedupeKey === secondDedupeKey
  ) {
    return true;
  }

  const firstName = getNormalizedGroupIdentityText(getGroupThreadName(firstBroadcast));
  const secondName = getNormalizedGroupIdentityText(getGroupThreadName(secondBroadcast));
  if (!firstName || firstName !== secondName) {
    return false;
  }

  const firstCreatedBy = String(firstBroadcast?.createdBy || '').trim();
  const secondCreatedBy = String(secondBroadcast?.createdBy || '').trim();
  if (firstCreatedBy && secondCreatedBy && firstCreatedBy === secondCreatedBy) {
    return true;
  }

  const firstMemberIds = new Set(
    getUniqueGroupMemberIds(firstBroadcast)
      .map((memberId) => String(memberId || '').trim().toLowerCase())
      .filter(Boolean)
  );
  const secondMemberIds = getUniqueGroupMemberIds(secondBroadcast)
    .map((memberId) => String(memberId || '').trim().toLowerCase())
    .filter(Boolean);
  const hasSharedMember = secondMemberIds.some((memberId) => firstMemberIds.has(memberId));
  if (hasSharedMember) {
    return true;
  }

  return Boolean(
    firstChatId &&
    secondChatId &&
    firstName &&
    (isBroadcastThreadId(firstChatId) || isBroadcastThreadId(secondChatId)) &&
    (isBackendObjectId(firstChatId) || isBackendObjectId(secondChatId))
  );
};

const mergeBroadcastMessageCacheAliases = ({
  messagesByChat = {},
  sourceChatId = '',
  targetChatId = '',
  currentUserId = '',
} = {}) => {
  const normalizedSourceChatId = String(sourceChatId || '').trim();
  const normalizedTargetChatId = String(targetChatId || '').trim();

  if (
    !normalizedSourceChatId ||
    !normalizedTargetChatId ||
    normalizedSourceChatId === normalizedTargetChatId
  ) {
    return messagesByChat;
  }

  const sourceMessages = messagesByChat[normalizedSourceChatId] || [];
  if (!sourceMessages.length) {
    return messagesByChat;
  }

  const targetMessages = messagesByChat[normalizedTargetChatId] || [];
  const mergedMessages = [...targetMessages];

  sourceMessages.forEach((message) => {
    if (mergedMessages.some((existingMessage) => messagesShareIdentity(existingMessage, message))) {
      return;
    }

    mergedMessages.push(
      normalizeMessageData(
        {
          ...message,
          chatId: normalizedTargetChatId,
          broadcastId: normalizedTargetChatId,
          chatType: 'broadcast',
        },
        {
          currentUserId,
          fallback: {
            ...message,
            chatId: normalizedTargetChatId,
            broadcastId: normalizedTargetChatId,
            chatType: 'broadcast',
          },
        }
      )
    );
  });

  const { [normalizedSourceChatId]: _removedSourceMessages, ...remainingMessagesByChat } = messagesByChat;
  return {
    ...remainingMessagesByChat,
    [normalizedTargetChatId]: mergedMessages.sort(
      (firstMessage, secondMessage) =>
        new Date(firstMessage.timestamp || firstMessage.createdAt || 0).getTime() -
        new Date(secondMessage.timestamp || secondMessage.createdAt || 0).getTime()
    ),
  };
};

const getMessageBroadcastThreadIdentity = (message = {}) => {
  const metadata = message?.metadata || {};
  const metadataBroadcast = metadata?.broadcast || {};

  return {
    chatId:
      message?.broadcastId ||
      metadata?.broadcastId ||
      metadataBroadcast?.broadcastId ||
      metadataBroadcast?.chatId ||
      '',
    broadcastId:
      message?.broadcastId ||
      metadata?.broadcastId ||
      metadataBroadcast?.broadcastId ||
      metadataBroadcast?.chatId ||
      '',
    groupId:
      message?.broadcastId ||
      metadata?.broadcastId ||
      metadataBroadcast?.groupId ||
      metadataBroadcast?.chatId ||
      '',
    broadcastName:
      metadataBroadcast?.broadcastName ||
      metadataBroadcast?.name ||
      metadata?.broadcastName ||
      '',
    groupName:
      metadataBroadcast?.broadcastName ||
      metadataBroadcast?.name ||
      metadata?.broadcastName ||
      '',
    name:
      metadataBroadcast?.broadcastName ||
      metadataBroadcast?.name ||
      metadata?.broadcastName ||
      '',
    createdBy: metadataBroadcast?.createdBy || metadata?.createdBy || message?.senderId || '',
    members:
      metadataBroadcast?.members ||
      metadataBroadcast?.recipientIds ||
      metadataBroadcast?.participantIds ||
      metadata?.recipientIds ||
      metadata?.participantIds ||
      [],
    isBroadcast: true,
    type: 'broadcast',
    chatType: 'broadcast',
  };
};

const isBroadcastMessageCacheBucket = (chatId = '', messages = []) => {
  const normalizedChatId = String(chatId || '').trim();
  return (
    isBroadcastThreadId(normalizedChatId) ||
    (Array.isArray(messages) && messages.some((message) =>
      Boolean(
        message?.broadcastId ||
        message?.chatType === 'broadcast' ||
        message?.metadata?.chatType === 'broadcast' ||
        message?.metadata?.broadcastId ||
        message?.metadata?.broadcast
      )
    ))
  );
};

const doesBroadcastMessageCacheMatchThread = ({
  chatId = '',
  messages = [],
  broadcast = {},
} = {}) => {
  const targetChatId = getGroupThreadChatId(broadcast);
  if (targetChatId && String(chatId || '').trim() === targetChatId) {
    return true;
  }

  return (Array.isArray(messages) ? messages : []).some((message) => {
    const messageBroadcast = getMessageBroadcastThreadIdentity(message);
    const messageBroadcastId = getGroupThreadChatId(messageBroadcast);
    if (targetChatId && messageBroadcastId === targetChatId) {
      return true;
    }

    return doBroadcastThreadsShareLocalIdentity(messageBroadcast, broadcast);
  });
};

const getBroadcastRecipientIds = (broadcast = {}, currentUserId = '') => {
  const normalizedCurrentUserId = String(currentUserId || '').trim();
  return getUniqueGroupMemberIds(broadcast).filter(
    (memberId) => String(memberId || '').trim() !== normalizedCurrentUserId
  );
};

const doGroupMemberIdsMatch = (firstMemberId = '', secondMemberId = '') => {
  const normalizedFirstMemberId = String(firstMemberId || '').trim();
  const normalizedSecondMemberId = String(secondMemberId || '').trim();

  if (!normalizedFirstMemberId || !normalizedSecondMemberId) {
    return false;
  }

  return (
    normalizedFirstMemberId === normalizedSecondMemberId ||
    arePhoneNumbersEquivalent(normalizedFirstMemberId, normalizedSecondMemberId)
  );
};

const doesGroupIncludeMember = (group = {}, memberId = '') => {
  const normalizedMemberId = String(memberId || '').trim();
  return Boolean(normalizedMemberId) && getUniqueGroupMemberIds(group).includes(normalizedMemberId);
};

const getNormalizedGroupRoleMemberIds = (group = {}, roleFieldName = 'admins') =>
  Array.isArray(group?.[roleFieldName])
    ? group[roleFieldName].map((member) => getGroupMemberId(member)).filter(Boolean)
    : [];

const resolveCurrentUserGroupMemberId = (group = {}, currentProfile = {}, fallbackUser = {}) => {
  const candidateMemberIds = Array.from(
    new Set([
      ...getNormalizedGroupRoleMemberIds(group, 'admins'),
      ...getNormalizedGroupRoleMemberIds(group, 'moderators'),
      ...getUniqueGroupMemberIds(group),
    ])
  );

  return (
    candidateMemberIds.find((memberId) =>
      isCurrentUserGroupMemberId(memberId, currentProfile, fallbackUser)
    ) || ''
  );
};

const canResolveCurrentUserGroupIdentity = (currentProfile = {}, fallbackUser = {}) => {
  const currentUserComparableIds = getCurrentUserComparableIds(currentProfile, fallbackUser);
  const currentUserPhone = resolveContactPhoneNumber(currentProfile) || resolveContactPhoneNumber(fallbackUser);

  return currentUserComparableIds.length > 0 || Boolean(currentUserPhone);
};

const canCurrentUserAccessGroup = (group = {}, currentProfile = {}, fallbackUser = {}) => {
  if (group?.isLocalDraft || group?.isLocallyCreated || group?.createdLocally) {
    return true;
  }

  // A thread the user left or was removed from stays reachable read-only, so the
  // history remains readable and the reason is visible in place.
  if (group?.hasLeftGroup || group?.removedFromGroup) {
    return true;
  }

  if (!canResolveCurrentUserGroupIdentity(currentProfile, fallbackUser)) {
    return true;
  }

  return getUniqueGroupMemberIds(group).some((memberId) =>
    isCurrentUserGroupMemberId(memberId, currentProfile, fallbackUser)
  );
};

const canCurrentUserForwardToGroup = (group = {}, currentProfile = {}, fallbackUser = {}) => {
  if (!group || group?.hasLeftGroup || group?.removedFromGroup) return false;
  if (group?.isLocalDraft || group?.isLocallyCreated || group?.createdLocally) return true;

  const memberIds = getUniqueGroupMemberIds(group);
  if (!memberIds.length || !canResolveCurrentUserGroupIdentity(currentProfile, fallbackUser)) {
    return true;
  }

  return memberIds.some((memberId) =>
    isCurrentUserGroupMemberId(memberId, currentProfile, fallbackUser)
  );
};

// True when an admin removed this account from the group. Distinct from
// `hasLeftGroup` (the user walked out themselves), because the two need different
// copy and only the removal can arrive without any local action. The explicit
// flag is set from the participant_removed broadcast; the roster check is the
// backstop for a removal this client only learns about on the next group sync.
const isCurrentUserRemovedFromGroup = (group = {}, currentProfile = {}, fallbackUser = {}) => {
  if (!group || group?.hasLeftGroup) return false;
  if (group?.removedFromGroup) return true;
  if (group?.isLocalDraft || group?.isLocallyCreated || group?.createdLocally) return false;

  if (!canResolveCurrentUserGroupIdentity(currentProfile, fallbackUser)) return false;

  const memberIds = getUniqueGroupMemberIds(group);
  // An empty roster means "not loaded yet", not "everyone was removed".
  if (!memberIds.length) return false;

  return !memberIds.some((memberId) =>
    isCurrentUserGroupMemberId(memberId, currentProfile, fallbackUser)
  );
};

const getCurrentUserGroupRole = (group = {}, currentProfile = {}, fallbackUser = {}) => {
  const currentGroupMemberId = resolveCurrentUserGroupMemberId(group, currentProfile, fallbackUser);

  if (!currentGroupMemberId) {
    return '';
  }

  if (getGroupMemberRole(group, currentGroupMemberId) === 'superadmin') return 'superadmin';

  if (
    getNormalizedGroupRoleMemberIds(group, 'admins').some((memberId) =>
      doGroupMemberIdsMatch(memberId, currentGroupMemberId)
    )
  ) {
    return 'admin';
  }

  if (
    getNormalizedGroupRoleMemberIds(group, 'moderators').some((memberId) =>
      doGroupMemberIdsMatch(memberId, currentGroupMemberId)
    )
  ) {
    return 'moderator';
  }

  return 'member';
};

const canNewGroupMembersViewPreviousMessages = (group = {}) =>
  normalizeGroupHistoryVisibilitySetting(
    group?.allowNewMembersToViewPreviousMessages,
    true
  );

const normalizeGroupRulesText = (group = {}) => {
  const rulesValue = group?.groupRules ?? group?.rules ?? '';
  return serializeGroupRulesText(rulesValue);
};

const getGroupRulesValidationMessage = (rulesText = '') => {
  const normalizedRulesText = String(rulesText || '').trim();

  if (normalizedRulesText.length < GROUP_RULES_MIN_LENGTH) {
    return `Group rules must be at least ${GROUP_RULES_MIN_LENGTH} characters.`;
  }

  if (normalizedRulesText.length > GROUP_RULES_MAX_LENGTH) {
    return `Group rules cannot exceed ${GROUP_RULES_MAX_LENGTH} characters.`;
  }

  return '';
};

const getGroupRulesCharacterCountLabel = (rulesLength = 0) => `${rulesLength} / ${GROUP_RULES_MAX_LENGTH}`;

const limitGroupRulesTextValue = (value = '') =>
  Array.from(String(value || '')).slice(0, GROUP_RULES_MAX_LENGTH).join('');

const limitInlineGroupRuleTextValue = (rules = [], draftId = '', nextText = '') => {
  const candidateRules = rules.map((rule) => (
    rule.draftId === draftId ? { ...rule, ruleText: nextText } : rule
  ));

  if (serializeGroupRulesText(candidateRules).length <= GROUP_RULES_MAX_LENGTH) {
    return nextText;
  }

  const nextTextCharacters = Array.from(String(nextText || ''));
  let low = 0;
  let high = nextTextCharacters.length;

  while (low < high) {
    const midpoint = Math.ceil((low + high) / 2);
    const candidateText = nextTextCharacters.slice(0, midpoint).join('');
    const candidateLength = serializeGroupRulesText(
      rules.map((rule) => (
        rule.draftId === draftId ? { ...rule, ruleText: candidateText } : rule
      ))
    ).length;

    if (candidateLength <= GROUP_RULES_MAX_LENGTH) {
      low = midpoint;
    } else {
      high = midpoint - 1;
    }
  }

  return nextTextCharacters.slice(0, low).join('');
};

const getBroadcastNameValidationMessage = (broadcastName = '') => {
  const normalizedBroadcastName = String(broadcastName || '').trim();

  if (!normalizedBroadcastName) {
    return 'Broadcast name is required.';
  }

  if (normalizedBroadcastName.length > BROADCAST_NAME_MAX_LENGTH) {
    return `Broadcast name cannot exceed ${BROADCAST_NAME_MAX_LENGTH} characters.`;
  }

  return '';
};

const getGroupRuleItems = (group = {}) => {
  return normalizeGroupRuleList(group?.groupRules ?? group?.rules ?? '', {
    createdBy: group?.createdBy || group?.creatorId || group?.ownerId,
    updatedAt: group?.updatedAt || group?.createdAt,
  });
};

const getGroupRulesPreviewText = (group = {}) => {
  const groupRuleItems = getGroupRuleItems(group);
  if (!groupRuleItems.length) {
    return 'No group rules added yet.';
  }

  return groupRuleItems.length === 1
    ? groupRuleItems[0].ruleText
    : `${groupRuleItems[0].ruleText} +${groupRuleItems.length - 1} more`;
};

const resolveGroupMemberJoinedAt = (group = {}, memberId = '') => {
  const normalizedMemberId = String(memberId || '').trim();
  if (!normalizedMemberId || !Array.isArray(group?.members)) {
    return '';
  }

  const matchedMember = group.members.find((member) =>
    doGroupMemberIdsMatch(getGroupMemberId(member), normalizedMemberId)
  );

  if (!matchedMember || typeof matchedMember !== 'object') {
    return '';
  }

  return String(matchedMember?.joinedAt || matchedMember?.joined_at || '').trim();
};

const resolveCurrentUserGroupJoinedAt = (group = {}, currentProfile = {}, fallbackUser = {}) => {
  const currentGroupMemberId = resolveCurrentUserGroupMemberId(group, currentProfile, fallbackUser);
  return currentGroupMemberId
    ? resolveGroupMemberJoinedAt(group, currentGroupMemberId)
    : '';
};

const getGroupHistoryVisibilityCutoffTimestamp = (
  group = {},
  currentProfile = {},
  fallbackUser = {}
) => {
  if (!isGroupThreadContact(group) || canNewGroupMembersViewPreviousMessages(group)) {
    return 0;
  }

  const joinedAtTimestamp = getPreviewTimestampValue(
    resolveCurrentUserGroupJoinedAt(group, currentProfile, fallbackUser)
  );
  const createdAtTimestamp = getPreviewTimestampValue(
    group?.createdAt || group?.timestamp || group?.updatedAt || null
  );

  if (!joinedAtTimestamp || !createdAtTimestamp || joinedAtTimestamp <= createdAtTimestamp) {
    return 0;
  }

  return joinedAtTimestamp;
};

const filterGroupMessagesByHistoryVisibility = (
  messages = [],
  group = {},
  currentProfile = {},
  fallbackUser = {}
) => {
  const normalizedMessages = Array.isArray(messages) ? messages : [];
  const historyVisibilityCutoff = getGroupHistoryVisibilityCutoffTimestamp(
    group,
    currentProfile,
    fallbackUser
  );

  if (!historyVisibilityCutoff) {
    return normalizedMessages;
  }

  return normalizedMessages.filter((message) => {
    if (isGroupCallLogNotificationMessage(message)) {
      return true;
    }

    const messageTimestamp = getPreviewTimestampValue(
      message?.timestamp || message?.createdAt || message?.time || null
    );

    return messageTimestamp >= historyVisibilityCutoff;
  });
};

const resolveGroupPinnedState = (group = {}, fallback = false) => {
  if (group?.isPinned !== undefined) return Boolean(group.isPinned);
  if (group?.pinned !== undefined) return Boolean(group.pinned);

  const currentUser = getStoredUser() || {};
  const currentUserId = String(currentUser?._id || currentUser?.userId || currentUser?.id || '').trim();
  const currentParticipant = (Array.isArray(group?.participants) ? group.participants : []).find((participant) => {
    const participantUser = participant?.user && typeof participant.user === 'object'
      ? participant.user
      : {};
    const participantId = String(
      participantUser?._id || participantUser?.userId || participantUser?.id ||
      participant?.user || participant?.userId || participant?.memberId || ''
    ).trim();
    return currentUserId && participantId === currentUserId;
  });

  return currentParticipant?.pinned !== undefined
    ? Boolean(currentParticipant.pinned)
    : Boolean(fallback);
};

const normalizeGroupThreadContact = (group = {}) => {
  const normalizedGroup = normalizeGroupData({
    ...group,
    groupId: getGroupThreadChatId(group),
    groupName: getGroupThreadName(group),
    groupPhoto:
      group?.groupPhoto ||
      group?.profilePic ||
      group?.avatar ||
      group?.photo ||
      '',
  });
  const normalizedChatId = getGroupThreadChatId(normalizedGroup);
  const storedDisappearingTimerRecord = getStoredDisappearingTimerRecord(normalizedChatId);
  const memberCount = Number(normalizedGroup?.memberCount || normalizedGroup?.members?.length || 0);
  const fallbackStatus = memberCount === 1 ? '1 member' : `${memberCount} members`;
  const normalizedTimestamp =
    normalizedGroup?.timestamp ||
    normalizedGroup?.updatedAt ||
    normalizedGroup?.lastMessageAt ||
    null;
  const normalizedGroupRules = getGroupRuleItems(group);
  const unreadCount = normalizeContactUnreadCount(normalizedGroup?.unreadCount);
  const lastReadUnreadCount = normalizeContactUnreadCount(normalizedGroup?.lastReadUnreadCount);
  const isUnread = Boolean(normalizedGroup?.isUnread || unreadCount > 0);
  const incomingDisappearingTimer = normalizeDisappearingMessageTimer(
    normalizedGroup.disappearingTimer,
    normalizedGroup.disappearingMessages,
    normalizedGroup.disappearAfter,
    group?.disappearingTimer,
    group?.disappearingMessages,
    group?.disappearAfter
  );
  const incomingDisappearingTimerUpdatedAt =
    normalizedGroup.disappearingTimerUpdatedAt ||
    normalizedGroup.disappearingMessagesUpdatedAt ||
    group?.disappearingTimerUpdatedAt ||
    group?.disappearingMessagesUpdatedAt ||
    null;
  const storedDisappearingTimerUpdatedAt = storedDisappearingTimerRecord?.updatedAt || null;
  const incomingTimerTime = new Date(incomingDisappearingTimerUpdatedAt || 0).getTime() || 0;
  const storedTimerTime = new Date(storedDisappearingTimerUpdatedAt || 0).getTime() || 0;
  const shouldUseStoredDisappearingTimer =
    Boolean(storedDisappearingTimerRecord?.timer) &&
    (
      !incomingDisappearingTimer ||
      !incomingDisappearingTimerUpdatedAt ||
      (storedTimerTime > 0 && storedTimerTime >= incomingTimerTime)
    );

  return {
    ...normalizedGroup,
    groupRules: normalizedGroupRules,
    rules: normalizedGroupRules,
    id: normalizedGroup.id || normalizedGroup.groupId || normalizedChatId,
    chatId: normalizedChatId,
    userId: null,
    name: normalizedGroup.groupName || 'Unnamed group',
    profilePic: normalizedGroup.groupPhoto || '',
    phone: '',
    status: normalizedGroup.description || fallbackStatus,
    isRegistered: true,
    lastMessageText:
      normalizedGroup.lastMessageText ||
      normalizedGroup.lastMessage ||
      '',
    lastMessageAt: normalizedGroup.lastMessageAt || normalizedTimestamp,
    lastMessageTime: normalizedGroup.lastMessageTime || normalizedTimestamp,
    updatedAt: normalizedGroup.updatedAt || normalizedTimestamp,
    unreadCount,
    lastReadUnreadCount,
    isUnread,
    isPinned: resolveGroupPinnedState(group, normalizedGroup?.isPinned),
    disappearingTimer: shouldUseStoredDisappearingTimer
      ? storedDisappearingTimerRecord.timer
      : (incomingDisappearingTimer || storedDisappearingTimerRecord?.timer || 'off'),
    disappearingTimerUpdatedAt: shouldUseStoredDisappearingTimer
      ? storedDisappearingTimerUpdatedAt
      : (incomingDisappearingTimerUpdatedAt || storedDisappearingTimerUpdatedAt || null),
  };
};

const mergeGroupThreadContact = (existingGroup = {}, incomingGroup = {}) => {
  const normalizedExistingGroup = normalizeGroupThreadContact(existingGroup);
  const normalizedIncomingGroup = normalizeGroupThreadContact(incomingGroup);
  const existingChatId = getGroupThreadChatId(normalizedExistingGroup);
  const incomingChatId = getGroupThreadChatId(normalizedIncomingGroup);
  const shouldUseIncomingIdentity =
    (!existingChatId && incomingChatId) ||
    (isBackendObjectId(incomingChatId) && !isBackendObjectId(existingChatId));
  const identitySource = shouldUseIncomingIdentity ? normalizedIncomingGroup : normalizedExistingGroup;
  const existingSortTime = getGroupSortTime(normalizedExistingGroup);
  const incomingSortTime = getGroupSortTime(normalizedIncomingGroup);
  const previewSource = incomingSortTime >= existingSortTime ? normalizedIncomingGroup : normalizedExistingGroup;
  const fallbackPreviewSource = previewSource === normalizedIncomingGroup
    ? normalizedExistingGroup
    : normalizedIncomingGroup;
  const normalizedChatId = getGroupThreadChatId(identitySource) || incomingChatId || existingChatId;
  const nextUnreadCount = Math.max(
    normalizeContactUnreadCount(normalizedExistingGroup.unreadCount),
    normalizeContactUnreadCount(normalizedIncomingGroup.unreadCount)
  );
  const shouldPreserveExistingMute = Boolean(normalizedExistingGroup.mutedPreference) &&
    normalizeNotificationMuted(normalizedExistingGroup.isMuted, normalizedExistingGroup.mutedUntil);

  return normalizeGroupThreadContact({
    ...normalizedExistingGroup,
    ...normalizedIncomingGroup,
    id: identitySource.id || normalizedChatId,
    groupId: normalizedChatId,
    chatId: normalizedChatId,
    groupName:
      normalizedIncomingGroup.groupName ||
      normalizedExistingGroup.groupName ||
      normalizedIncomingGroup.name ||
      normalizedExistingGroup.name,
    members: normalizedIncomingGroup.members?.length
      ? normalizedIncomingGroup.members
      : normalizedExistingGroup.members,
    admins: normalizedIncomingGroup.admins?.length
      ? normalizedIncomingGroup.admins
      : normalizedExistingGroup.admins,
    moderators: normalizedIncomingGroup.moderators?.length
      ? normalizedIncomingGroup.moderators
      : normalizedExistingGroup.moderators,
    lastMessageText: previewSource.lastMessageText || fallbackPreviewSource.lastMessageText || '',
    lastMessage: previewSource.lastMessage || fallbackPreviewSource.lastMessage || '',
    lastMessageAt: previewSource.lastMessageAt || fallbackPreviewSource.lastMessageAt || null,
    lastMessageTime: previewSource.lastMessageTime || fallbackPreviewSource.lastMessageTime || null,
    updatedAt: previewSource.updatedAt || fallbackPreviewSource.updatedAt || null,
    timestamp: previewSource.timestamp || fallbackPreviewSource.timestamp || null,
    unreadCount: nextUnreadCount,
    isUnread: Boolean(normalizedExistingGroup.isUnread || normalizedIncomingGroup.isUnread || nextUnreadCount > 0),
    isMuted: shouldPreserveExistingMute
      ? true
      : normalizeNotificationMuted(normalizedIncomingGroup.isMuted, normalizedIncomingGroup.mutedUntil),
    mutedUntil: shouldPreserveExistingMute
      ? normalizedExistingGroup.mutedUntil
      : (normalizedIncomingGroup.mutedUntil || null),
    mutedPreference: shouldPreserveExistingMute
      ? normalizedExistingGroup.mutedPreference
      : (normalizedIncomingGroup.mutedPreference || ''),
    disappearingTimer: normalizedIncomingGroup.disappearingTimer || normalizedExistingGroup.disappearingTimer || 'off',
    disappearingTimerUpdatedAt: normalizedIncomingGroup.disappearingTimerUpdatedAt || normalizedExistingGroup.disappearingTimerUpdatedAt || null,
  });
};

const dedupeGroupThreads = (groups = []) => {
  const groupsByKey = new Map();

  groups.forEach((group) => {
    const normalizedGroup = normalizeGroupThreadContact(group);
    if (!normalizedGroup.chatId) {
      return;
    }

    const groupKey = getGroupThreadDedupeKey(normalizedGroup) || `id:${normalizedGroup.chatId}`;
    const existingGroup = groupsByKey.get(groupKey);
    groupsByKey.set(
      groupKey,
      existingGroup ? mergeGroupThreadContact(existingGroup, normalizedGroup) : normalizedGroup
    );
  });

  return sortGroupsByRecent(Array.from(groupsByKey.values()));
};

const normalizeApiGroupThreadContact = (group = {}, fallback = {}) => {
  const apiParticipants = Array.isArray(group?.participants) ? group.participants : [];
  const participantModels = apiParticipants
    .map((participant) => {
      const participantUser =
        participant?.user && typeof participant.user === 'object'
          ? participant.user
          : {};
      const memberId = String(
        participantUser?._id ||
          participantUser?.id ||
          participant?.user ||
          participant?.userId ||
          participant?.memberId ||
          ''
      ).trim();

      if (!memberId) return null;

      return {
        memberId,
        userId: memberId,
        role: String(participant?.role || 'member').trim().toLowerCase(),
        joinedAt: participant?.joinedAt || participant?.createdAt || group?.createdAt || fallback?.createdAt,
        name: participantUser?.name || participantUser?.fullName || '',
        phone: participantUser?.phone || '',
        profilePic: participantUser?.profilePic || '',
      };
    })
    .filter(Boolean);
  const admins = participantModels
    .filter((participant) => participant.role === 'admin' || participant.role === 'superadmin')
    .map((participant) => participant.memberId);
  const moderators = participantModels
    .filter((participant) => participant.role === 'moderator')
    .map((participant) => participant.memberId);

  return normalizeGroupThreadContact({
    ...fallback,
    ...group,
    groupId: group?._id || group?.id || group?.groupId || fallback?.groupId,
    chatId: group?._id || group?.id || group?.groupId || fallback?.chatId,
    groupName: group?.groupName || group?.name || fallback?.groupName,
    groupPhoto: group?.groupPhoto || fallback?.groupPhoto,
    description: group?.description ?? fallback?.description,
    isPinned: resolveGroupPinnedState(group, fallback?.isPinned),
    createdBy: group?.createdBy?._id || group?.createdBy?.id || group?.createdBy || fallback?.createdBy,
    members: participantModels.length ? participantModels : fallback?.members,
    admins: Array.isArray(group?.participants) ? admins : fallback?.admins,
    moderators: Array.isArray(group?.participants) ? moderators : fallback?.moderators,
    adminPermissionSettings: {
      ...(fallback?.adminPermissionSettings || {}),
      ...groupPermissionSettingsFromApi(group?.settings),
    },
    lastMessage: fallback?.lastMessage || '',
    lastMessageText: fallback?.lastMessageText || '',
    timestamp: fallback?.timestamp || Date.now(),
    createdAt: group?.createdAt || fallback?.createdAt,
    updatedAt: group?.updatedAt || fallback?.updatedAt,
  });
};

const normalizeBroadcastThreadContact = (broadcast = {}) => {
  const normalizedBroadcast = normalizeGroupData({
    ...broadcast,
    groupId: getGroupThreadChatId(broadcast),
    groupName: getGroupThreadName(broadcast),
    groupPhoto:
      broadcast?.broadcastPhoto ||
      broadcast?.groupPhoto ||
      broadcast?.profilePic ||
      broadcast?.avatar ||
      broadcast?.photo ||
      '',
  });
  const normalizedChatId = getGroupThreadChatId(normalizedBroadcast);
  const memberCount = Number(normalizedBroadcast?.memberCount || normalizedBroadcast?.members?.length || 0);
  const fallbackStatus = memberCount === 1 ? '1 recipient' : `${memberCount} recipients`;
  const normalizedTimestamp =
    normalizedBroadcast?.timestamp ||
    normalizedBroadcast?.updatedAt ||
    normalizedBroadcast?.lastMessageAt ||
    null;
  const unreadCount = normalizeContactUnreadCount(normalizedBroadcast?.unreadCount);
  const isUnread = Boolean(normalizedBroadcast?.isUnread || unreadCount > 0);

  return {
    ...normalizedBroadcast,
    broadcastId: normalizedChatId,
    broadcastName: normalizedBroadcast.groupName || '',
    broadcastPhoto: normalizedBroadcast.groupPhoto || '',
    groupRules: [],
    rules: [],
    id: normalizedBroadcast.id || normalizedChatId,
    chatId: normalizedChatId,
    userId: null,
    name: normalizedBroadcast.groupName || 'Unnamed broadcast',
    profilePic: normalizedBroadcast.groupPhoto || '',
    phone: '',
    status: normalizedBroadcast.description || fallbackStatus,
    isRegistered: true,
    isBroadcast: true,
    isGroup: false,
    type: 'broadcast',
    chatType: 'broadcast',
    lastMessageText:
      normalizedBroadcast.lastMessageText ||
      normalizedBroadcast.lastMessage ||
      '',
    lastMessageAt: normalizedBroadcast.lastMessageAt || normalizedTimestamp,
    lastMessageTime: normalizedBroadcast.lastMessageTime || normalizedTimestamp,
    updatedAt: normalizedBroadcast.updatedAt || normalizedTimestamp,
    unreadCount,
    isUnread,
  };
};

const mergeBroadcastThreadContact = (existingBroadcast = {}, incomingBroadcast = {}) => {
  const normalizedExistingBroadcast = normalizeBroadcastThreadContact(existingBroadcast);
  const normalizedIncomingBroadcast = normalizeBroadcastThreadContact(incomingBroadcast);
  const existingChatId = getGroupThreadChatId(normalizedExistingBroadcast);
  const incomingChatId = getGroupThreadChatId(normalizedIncomingBroadcast);
  const shouldUseIncomingIdentity =
    (!existingChatId && incomingChatId) ||
    (isBackendObjectId(incomingChatId) && !isBackendObjectId(existingChatId));
  const identitySource = shouldUseIncomingIdentity
    ? normalizedIncomingBroadcast
    : normalizedExistingBroadcast;
  const existingSortTime = getGroupSortTime(normalizedExistingBroadcast);
  const incomingSortTime = getGroupSortTime(normalizedIncomingBroadcast);
  const previewSource =
    incomingSortTime >= existingSortTime ? normalizedIncomingBroadcast : normalizedExistingBroadcast;
  const fallbackPreviewSource =
    previewSource === normalizedIncomingBroadcast
      ? normalizedExistingBroadcast
      : normalizedIncomingBroadcast;
  const normalizedChatId =
    getGroupThreadChatId(identitySource) || incomingChatId || existingChatId;
  const nextUnreadCount = Math.max(
    normalizeContactUnreadCount(normalizedExistingBroadcast.unreadCount),
    normalizeContactUnreadCount(normalizedIncomingBroadcast.unreadCount)
  );

  return normalizeBroadcastThreadContact({
    ...normalizedExistingBroadcast,
    ...normalizedIncomingBroadcast,
    id: identitySource.id || normalizedChatId,
    broadcastId: normalizedChatId,
    groupId: normalizedChatId,
    chatId: normalizedChatId,
    broadcastName:
      normalizedIncomingBroadcast.broadcastName ||
      normalizedExistingBroadcast.broadcastName ||
      normalizedIncomingBroadcast.name ||
      normalizedExistingBroadcast.name,
    groupName:
      normalizedIncomingBroadcast.groupName ||
      normalizedExistingBroadcast.groupName ||
      normalizedIncomingBroadcast.name ||
      normalizedExistingBroadcast.name,
    broadcastPhoto:
      normalizedIncomingBroadcast.broadcastPhoto ||
      normalizedExistingBroadcast.broadcastPhoto ||
      normalizedIncomingBroadcast.groupPhoto ||
      normalizedExistingBroadcast.groupPhoto,
    groupPhoto:
      normalizedIncomingBroadcast.groupPhoto ||
      normalizedExistingBroadcast.groupPhoto ||
      normalizedIncomingBroadcast.broadcastPhoto ||
      normalizedExistingBroadcast.broadcastPhoto,
    members: normalizedIncomingBroadcast.members?.length
      ? normalizedIncomingBroadcast.members
      : normalizedExistingBroadcast.members,
    admins: normalizedIncomingBroadcast.admins?.length
      ? normalizedIncomingBroadcast.admins
      : normalizedExistingBroadcast.admins,
    moderators: normalizedIncomingBroadcast.moderators?.length
      ? normalizedIncomingBroadcast.moderators
      : normalizedExistingBroadcast.moderators,
    createdBy:
      normalizedIncomingBroadcast.createdBy || normalizedExistingBroadcast.createdBy,
    description:
      normalizedIncomingBroadcast.description ?? normalizedExistingBroadcast.description,
    lastMessageText:
      previewSource.lastMessageText || fallbackPreviewSource.lastMessageText || '',
    lastMessage: previewSource.lastMessage || fallbackPreviewSource.lastMessage || '',
    lastMessageAt:
      previewSource.lastMessageAt || fallbackPreviewSource.lastMessageAt || null,
    lastMessageTime:
      previewSource.lastMessageTime || fallbackPreviewSource.lastMessageTime || null,
    updatedAt: previewSource.updatedAt || fallbackPreviewSource.updatedAt || null,
    timestamp: previewSource.timestamp || fallbackPreviewSource.timestamp || null,
    unreadCount: nextUnreadCount,
    isUnread: Boolean(
      normalizedExistingBroadcast.isUnread ||
      normalizedIncomingBroadcast.isUnread ||
      nextUnreadCount > 0
    ),
  });
};

const dedupeBroadcastThreads = (broadcasts = []) => {
  const broadcastsByKey = new Map();

  broadcasts.forEach((broadcast) => {
    const normalizedBroadcast = normalizeBroadcastThreadContact(broadcast);
    if (!normalizedBroadcast.chatId) {
      return;
    }

    const broadcastKey =
      getGroupThreadDedupeKey(normalizedBroadcast) || `id:${normalizedBroadcast.chatId}`;
    const existingBroadcast = broadcastsByKey.get(broadcastKey);
    broadcastsByKey.set(
      broadcastKey,
      existingBroadcast
        ? mergeBroadcastThreadContact(existingBroadcast, normalizedBroadcast)
        : normalizedBroadcast
    );
  });

  return sortGroupsByRecent(Array.from(broadcastsByKey.values()));
};
const normalizeApiBroadcastThreadContact = (broadcast = {}, fallback = {}) => {
  const apiParticipants = Array.isArray(broadcast?.participants) ? broadcast.participants : [];
  const participantModels = apiParticipants
    .map((participant) => {
      const participantUser =
        participant?.user && typeof participant.user === 'object'
          ? participant.user
          : participant && typeof participant === 'object'
            ? participant
            : {};
      const memberId = String(
        participantUser?._id ||
          participantUser?.id ||
          participantUser?.userId ||
          participant?.user ||
          participant?.userId ||
          participant?.memberId ||
          participant ||
          ''
      ).trim();

      if (!memberId) return null;

      return {
        memberId,
        userId: memberId,
        role: 'member',
        joinedAt: participant?.joinedAt || participant?.createdAt || broadcast?.createdAt || fallback?.createdAt,
        name: participantUser?.name || participantUser?.fullName || '',
        phone: participantUser?.phone || '',
        profilePic: participantUser?.profilePic || '',
      };
    })
    .filter(Boolean);
  const createdBy = broadcast?.createdBy?._id || broadcast?.createdBy?.id || broadcast?.createdBy || fallback?.createdBy;

  return normalizeBroadcastThreadContact({
    ...fallback,
    ...broadcast,
    broadcastId: broadcast?._id || broadcast?.id || broadcast?.broadcastId || fallback?.broadcastId,
    groupId: broadcast?._id || broadcast?.id || broadcast?.broadcastId || fallback?.groupId,
    chatId: broadcast?._id || broadcast?.id || broadcast?.broadcastId || fallback?.chatId,
    broadcastName: broadcast?.name || broadcast?.broadcastName || fallback?.broadcastName,
    groupName: broadcast?.name || broadcast?.broadcastName || fallback?.groupName,
    broadcastPhoto: broadcast?.broadcastPhoto || broadcast?.groupPhoto || fallback?.broadcastPhoto,
    groupPhoto: broadcast?.broadcastPhoto || broadcast?.groupPhoto || fallback?.groupPhoto,
    description: broadcast?.description ?? fallback?.description,
    createdBy,
    // Keep the populated participant records intact. Reducing this to IDs here
    // discarded their names/details before the Broadcast Info panel rendered.
    members: participantModels,
    admins: createdBy ? [createdBy] : fallback?.admins,
    moderators: fallback?.moderators || [],
    lastMessage: fallback?.lastMessage || '',
    lastMessageText: fallback?.lastMessageText || '',
    timestamp: fallback?.timestamp || broadcast?.updatedAt || broadcast?.createdAt || Date.now(),
    createdAt: broadcast?.createdAt || fallback?.createdAt,
    updatedAt: broadcast?.updatedAt || fallback?.updatedAt,
  });
};

const DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS = Object.freeze({
  sendMessages: 'everyone',
  addMembers: 'admins-moderators',
  mediaSharing: 'enabled',
  approveNewMembers: true,
  slowMode: false,
  inviteViaLink: true,
  moderatorAddMembers: true,
  moderatorAssignRoles: true,
  pinMessages: true,
  editGroupInfo: true,
  manageReports: true,
});

const isPlainObjectRecord = (value) =>
  Boolean(value && typeof value === 'object' && !Array.isArray(value));

const normalizePermissionAudienceSetting = (value, fallbackValue = 'everyone') => {
  const normalizedValue = String(value || fallbackValue || 'everyone').trim().toLowerCase();

  if (normalizedValue === 'admins') {
    return 'admins';
  }

  if (normalizedValue === 'admins-moderators' || normalizedValue === 'moderators-admins') {
    return 'admins-moderators';
  }

  return 'everyone';
};

const normalizeMediaSharingSetting = (value, fallbackValue = 'enabled') => {
  const normalizedValue = String(value || fallbackValue || 'enabled').trim().toLowerCase();

  if (normalizedValue === 'photos-only') {
    return 'photos-only';
  }

  if (normalizedValue === 'disabled') {
    return 'disabled';
  }

  return 'enabled';
};

const normalizeGroupAdminPermissionSettings = (settings = {}) => {
  const source = isPlainObjectRecord(settings) ? settings : {};

  return {
    sendMessages: normalizePermissionAudienceSetting(
      source.sendMessages ?? source.whoCanSendMessages,
      DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.sendMessages
    ),
    addMembers: normalizePermissionAudienceSetting(
      source.addMembers ?? source.whoCanAddMembers,
      DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.addMembers
    ),
    mediaSharing: normalizeMediaSharingSetting(
      source.mediaSharing ?? source.mediaShare ?? source.mediaAccess,
      DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.mediaSharing
    ),
    approveNewMembers:
      typeof source.approveNewMembers === 'boolean'
        ? source.approveNewMembers
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.approveNewMembers,
    slowMode:
      typeof source.slowMode === 'boolean'
        ? source.slowMode
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.slowMode,
    inviteViaLink:
      typeof source.inviteViaLink === 'boolean'
        ? source.inviteViaLink
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.inviteViaLink,
    moderatorAddMembers:
      typeof source.moderatorAddMembers === 'boolean'
        ? source.moderatorAddMembers
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.moderatorAddMembers,
    moderatorAssignRoles:
      typeof source.moderatorAssignRoles === 'boolean'
        ? source.moderatorAssignRoles
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.moderatorAssignRoles,
    pinMessages:
      typeof source.pinMessages === 'boolean'
        ? source.pinMessages
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.pinMessages,
    editGroupInfo:
      typeof source.editGroupInfo === 'boolean'
        ? source.editGroupInfo
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.editGroupInfo,
    manageReports:
      typeof source.manageReports === 'boolean'
        ? source.manageReports
        : DEFAULT_GROUP_ADMIN_PERMISSION_SETTINGS.manageReports,
  };
};

const getGroupAdminPermissionSettings = (group = {}) =>
  normalizeGroupAdminPermissionSettings(
    group?.adminPermissionSettings ??
      group?.groupAdminPermissionSettings ??
      group?.permissionSettings
  );

const doesPermissionAudienceAllowRole = (audience = 'everyone', role = 'member') => {
  const normalizedRole = normalizePermissionRole(role);
  const normalizedAudience = normalizePermissionAudienceSetting(audience);

  if (normalizedRole === 'superadmin') return true;

  if (normalizedAudience === 'admins') {
    return normalizedRole === 'admin';
  }

  if (normalizedAudience === 'admins-moderators') {
    return normalizedRole === 'admin' || normalizedRole === 'moderator';
  }

  return true;
};

const getParticipantRoleKey = (participant = {}) => {
  if (participant?.isGroupSuperAdmin || participant?.role === 'superadmin') return 'superadmin';
  if (participant?.isGroupAdmin) return 'admin';
  if (participant?.isGroupModerator) return 'moderator';
  return normalizePermissionRole(participant?.role || participant?.memberRole || 'member');
};

const resolveParticipantAdminPermissions = (participant = {}, role = 'member') => {
  const normalizedRole = normalizePermissionRole(role);
  const permissionSource = isPlainObjectRecord(participant?.adminPermissions)
    ? participant.adminPermissions
    : isPlainObjectRecord(participant?.permissions)
      ? participant.permissions
      : {};
  const isMuted = Boolean(participant?.isMuted ?? participant?.muted);
  const isRestricted = Boolean(participant?.isRestricted ?? participant?.restricted);
  let permissions = createPermissionsModel(permissionSource, { role: normalizedRole });

  permissions = setMuted(permissions, isMuted);

  if (isRestricted) {
    permissions = restrictMemberPermissions(permissions);
  }

  return permissions;
};

const buildParticipantAdminPermissions = ({
  role = 'member',
  permissions = {},
  isMuted = false,
  isRestricted = false,
  resetToRoleDefaults = false,
} = {}) => {
  const normalizedRole = normalizePermissionRole(role);
  let nextPermissions = resetToRoleDefaults
    ? getDefaultPermissionsForRole(normalizedRole)
    : createPermissionsModel(permissions, { role: normalizedRole });

  nextPermissions = setMuted(nextPermissions, isMuted);

  if (isRestricted) {
    nextPermissions = restrictMemberPermissions(nextPermissions);
  }

  return nextPermissions;
};

const getCurrentUserSelectedGroupAdminState = ({
  group,
  currentUserId,
  currentUserProfile,
  storedUser,
} = {}) => {
  if (!group || !isGroupThreadContact(group)) {
    return {
      role: '',
      adminPermissions: null,
      canAddParticipants: false,
      canRemoveMembers: false,
    };
  }

  const currentUserGroupRole = getCurrentUserGroupRole(group, currentUserProfile, storedUser);
  const currentUserMemberId =
    resolveCurrentUserGroupMemberId(group, currentUserProfile, storedUser) ||
    String(currentUserId || '').trim();
  const matchedMember =
    (Array.isArray(group?.members) ? group.members : []).find((member) =>
      doGroupMemberIdsMatch(getGroupMemberId(member), currentUserMemberId)
    ) || {};
  const adminPermissions = resolveParticipantAdminPermissions(
    matchedMember,
    currentUserGroupRole || matchedMember?.role || 'member'
  );
  const groupPermissionSettings = getGroupAdminPermissionSettings(group);

  return {
    role: currentUserGroupRole,
    adminPermissions,
    canAddParticipants:
      !group?.hasLeftGroup && !group?.removedFromGroup && !matchedMember?.isRestricted &&
      (isGroupAdminRole(currentUserGroupRole) ||
        (currentUserGroupRole === 'moderator' && groupPermissionSettings.moderatorAddMembers) ||
        (currentUserGroupRole === 'member' && groupPermissionSettings.addMembers === 'everyone')),
    canRemoveMembers:
      Boolean(adminPermissions?.canRemoveMembers) &&
      (isGroupAdminRole(currentUserGroupRole) || currentUserGroupRole === 'moderator'),
  };
};

const buildChatThreadRoute = (chatId, moduleName = CHAT_MODULES.chats) => {
  const normalizedChatId = String(chatId || '').trim();
  if (!normalizedChatId) {
    return getChatModuleRootRoute(moduleName);
  }

  return normalizeChatModule(moduleName) === CHAT_MODULES.groups
    ? `/groups/chat/${encodeURIComponent(normalizedChatId)}`
    : normalizeChatModule(moduleName) === CHAT_MODULES.broadcasts
      ? `/broadcasts/chat/${encodeURIComponent(normalizedChatId)}`
    : `/chat/${encodeURIComponent(normalizedChatId)}`;
};

const buildChatCallRoute = (chatId) => {
  const normalizedChatId = String(chatId || '').trim();
  return normalizedChatId ? `/chat/${encodeURIComponent(normalizedChatId)}/call` : getChatModuleRootRoute();
};

const resolveContactThreadModule = (contact, preferredModule = CHAT_MODULES.chats) => {
  const normalizedPreferredModule = normalizeChatModule(preferredModule);

  if (
    (normalizedPreferredModule === CHAT_MODULES.groups ||
      normalizedPreferredModule === CHAT_MODULES.broadcasts) &&
    !isGroupThreadContact(contact)
  ) {
    return CHAT_MODULES.chats;
  }

  if (normalizedPreferredModule === CHAT_MODULES.groups && isBroadcastThreadContact(contact)) {
    return CHAT_MODULES.broadcasts;
  }

  if (normalizedPreferredModule === CHAT_MODULES.broadcasts && !isBroadcastThreadContact(contact)) {
    return isGroupThreadContact(contact) ? CHAT_MODULES.groups : CHAT_MODULES.chats;
  }

  return normalizedPreferredModule;
};

const resolveEndedCallStateFromLog = (callLog = {}) => {
  const normalizedStatus = String(callLog?.status || '').trim();

  if (normalizedStatus === CALL_LOG_STATUS.MISSED) {
    return CALL_STATUS.MISSED;
  }

  if (normalizedStatus === CALL_LOG_STATUS.REJECTED) {
    return CALL_STATUS.REJECTED;
  }

  return CALL_STATUS.ENDED;
};

