const CallDirectionIcon = ({ status, direction = '', size = 13 }) => {
  const isMissed = status === CALL_LOG_STATUS.MISSED;
  const isRejected = status === CALL_LOG_STATUS.REJECTED;
  const isIncoming =
    normalizeCallLogDirection(direction, CALL_LOG_DIRECTION.OUTGOING) === CALL_LOG_DIRECTION.INCOMING;

  // Missed call: an inbound call that was never answered — a down-left arrow.
  if (isMissed && isIncoming) {
    return (
      <svg width="12" height="7" viewBox="0 0 12 7" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <path d="M4.15516 0.601562H0.599609V4.15712M0.599609 0.601562L5.93294 5.9349L11.2663 0.601562" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }

  // Declined call: a handset with a slash through it, so it never reads the same
  // as a missed call in the history list.
  if (isRejected) {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        <path d="M4.5 6.5a13 13 0 0 0 13 13l2.2-2.2-3.3-2.2-1.9 1.2a10.6 10.6 0 0 1-4.8-4.8l1.2-1.9-2.2-3.3z" />
        <path d="M4 20 20 4" />
      </svg>
    );
  }

  return (
    <svg width={size} height={size} viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {isIncoming ? (
        <>
          <path d="M13.7 4.3 4.8 13.2" />
          <path d="M4.8 13.2h6.1" />
          <path d="M4.8 13.2V7.1" />
        </>
      ) : (
        <>
          <path d="M4.3 13.7 13.2 4.8" />
          <path d="M13.2 4.8H7.1" />
          <path d="M13.2 4.8v6.1" />
        </>
      )}
    </svg>
  );
};

const getChatCallMessagePresentation = (message = {}, isSent = false) => {
  const callText = getMessageCallText(message).toLowerCase();
  const rawCallStatus = getMessageCallStatus(message);
  const rawCallType = String(
    message?.callType || message?.metadata?.callType || ''
  ).trim().toLowerCase();
  const callType = rawCallType === CALL_TYPE.VIDEO || /\bvideo\b/.test(callText)
    ? CALL_TYPE.VIDEO
    : CALL_TYPE.AUDIO;
  const isRejected = rawCallStatus === 'rejected' || /\b(?:rejected|declined)\b/.test(callText);
  const isNotAnswered = rawCallStatus === 'not_answered' || /\bnot answered\b/.test(callText);
  const isCancelled = ['cancelled', 'canceled'].includes(rawCallStatus) || /\bcancelled|\bcanceled/.test(callText);
  const isMissed = rawCallStatus === 'missed' || /\bmissed\b/.test(callText);
  const isStarted = rawCallStatus === 'started';
  const isGroupCall = /\bgroup call\b/.test(callText) || Boolean(message?.groupCallId || message?.metadata?.groupCallId);
  const status = isRejected
    ? CALL_LOG_STATUS.REJECTED
    : (isMissed || isNotAnswered || isCancelled)
      ? CALL_LOG_STATUS.MISSED
      : CALL_LOG_STATUS.COMPLETED;
  const direction = isMissed
    ? CALL_LOG_DIRECTION.INCOMING
    : isNotAnswered || isCancelled
      ? CALL_LOG_DIRECTION.OUTGOING
      : isSent
        ? CALL_LOG_DIRECTION.OUTGOING
        : CALL_LOG_DIRECTION.INCOMING;
  const statusLabel = isRejected
    ? 'Rejected'
    : isMissed
      ? 'Missed'
      : isNotAnswered
        ? 'Not answered'
        : isCancelled
          ? 'Cancelled'
          : isStarted
            ? 'Started'
            : 'Completed';
  const mediaLabel = callType === CALL_TYPE.VIDEO ? 'Video' : 'Audio';
  // How long the call was connected, read from the log text ("(125s)" from the
  // backend, "(02:05)" once formatted) and shown as minutes and seconds.
  const structuredDuration = Number(
    message?.duration ??
      message?.callDuration ??
      message?.metadata?.duration ??
      message?.metadata?.callDuration ??
      message?.callId?.duration
  );
  const parsedDuration = parseCallLogDurationSeconds(getMessageCallText(message));
  const connectedDurationSeconds = status === CALL_LOG_STATUS.COMPLETED && !isStarted
    ? Number.isFinite(structuredDuration) && structuredDuration >= 0
      ? Math.round(structuredDuration)
      : parsedDuration
    : null;

  return {
    callType,
    direction,
    status,
    statusLabel,
    durationLabel: connectedDurationSeconds !== null ? formatCallDuration(connectedDurationSeconds) : '',
    title: `${callType === CALL_TYPE.VIDEO ? mediaLabel : 'Voice'}${isGroupCall ? ' Group' : ''} Call`,
    isFailure: status !== CALL_LOG_STATUS.COMPLETED,
  };
};

const ChatCallMessageCard = ({ message, isSent = false, senderLabel = null, footer = null }) => {
  const presentation = getChatCallMessagePresentation(message, isSent);

  return (
    <div
      className="w-fit min-w-[224px] max-w-[320px] rounded-[12px] border border-[#DCE3EC] bg-white px-3.5 py-3 shadow-[0_6px_16px_rgba(15,23,42,0.07)]"
      role="note"
      aria-label={[presentation.title, presentation.statusLabel, presentation.durationLabel].filter(Boolean).join(', ')}
    >
      {senderLabel}
      <div className="flex items-center gap-3">
        <span className={`flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full ${presentation.isFailure ? 'bg-[#FFF1F2] text-[#E11D48]' : 'bg-[#EEF2FF] text-[#6D28D9]'}`} aria-hidden="true">
          {presentation.callType === CALL_TYPE.VIDEO
            ? <VideoCallIcon size={20} />
            : <AudioCallIcon size={20} />}
        </span>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-[14px] font-semibold leading-5 text-[#172033]">
            {presentation.title}
          </span>
          <span className={`mt-0.5 flex items-center gap-1.5 text-[12px] font-medium leading-4 ${presentation.isFailure ? 'text-[#E11D48]' : 'text-[#64748B]'}`}>
            <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center" aria-hidden="true">
              <CallDirectionIcon
                status={presentation.status}
                direction={presentation.direction}
                size={14}
              />
            </span>
            <span>{presentation.statusLabel}</span>
            {presentation.durationLabel ? (
              <>
                <span aria-hidden="true">•</span>
                <span className="tabular-nums">{presentation.durationLabel}</span>
              </>
            ) : null}
          </span>
        </span>
      </div>
      {footer}
    </div>
  );
};

