const ChatMuteIndicator = ({ thread }) => {
  const mutedUntil = thread?.mutedUntil || null;
  const [, refreshAfterExpiry] = useState(0);
  const isMuted = normalizeNotificationMuted(thread?.isMuted, mutedUntil);

  useEffect(() => {
    if (!isMuted || !mutedUntil) return undefined;

    const expiryTime = new Date(mutedUntil).getTime();
    if (!Number.isFinite(expiryTime)) return undefined;

    const remainingMs = expiryTime - Date.now();
    if (remainingMs <= 0) return undefined;

    const timeoutId = window.setTimeout(
      () => refreshAfterExpiry((version) => version + 1),
      Math.min(remainingMs + 25, 2_147_483_647)
    );
    return () => window.clearTimeout(timeoutId);
  }, [isMuted, mutedUntil]);

  if (!isMuted) return null;

  return (
    <span
      className="inline-flex h-4 w-4 flex-shrink-0 items-center justify-center text-[#64748B]"
      title="Notifications muted"
      aria-label="Notifications muted"
      role="img"
    >
      <MuteNotificationsIcon size={14} />
    </span>
  );
};

