const StarredMediaBubbleIcon = ({ className = '', onRemove }) => {
  const longPressTimeoutRef = useRef(null);
  const pressStartRef = useRef({ pointerId: null, x: 0, y: 0 });

  const clearLongPress = useCallback(() => {
    if (!longPressTimeoutRef.current) return;
    window.clearTimeout(longPressTimeoutRef.current);
    longPressTimeoutRef.current = null;
  }, []);

  useEffect(() => clearLongPress, [clearLongPress]);

  const handlePointerDown = (event) => {
    if (typeof event.button === 'number' && event.button !== 0) return;
    event.stopPropagation();
    clearLongPress();
    pressStartRef.current = {
      pointerId: typeof event.pointerId === 'number' ? event.pointerId : null,
      x: Number(event.clientX) || 0,
      y: Number(event.clientY) || 0,
    };
    longPressTimeoutRef.current = window.setTimeout(() => {
      longPressTimeoutRef.current = null;
      onRemove?.();
      window.navigator?.vibrate?.(10);
    }, MESSAGE_LONG_PRESS_DURATION_MS);
  };

  const handlePointerMove = (event) => {
    const pressStart = pressStartRef.current;
    if (
      pressStart.pointerId !== null &&
      typeof event.pointerId === 'number' &&
      pressStart.pointerId !== event.pointerId
    ) {
      return;
    }

    const movedDistance = Math.hypot(
      (Number(event.clientX) || 0) - pressStart.x,
      (Number(event.clientY) || 0) - pressStart.y
    );
    if (movedDistance > MESSAGE_LONG_PRESS_MOVE_THRESHOLD_PX) clearLongPress();
  };

  return (
    <button
      type="button"
      className={`absolute right-1.5 top-1.5 z-[4] flex h-8 w-8 select-none items-center justify-center rounded-full text-[#FDE047] ${className}`}
      aria-label="Starred media. Long press to remove star"
      title="Long press to remove star"
      data-disable-message-long-press="true"
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(event) => {
        event.stopPropagation();
        clearLongPress();
      }}
      onPointerCancel={clearLongPress}
      onPointerLeave={clearLongPress}
      onContextMenu={(event) => event.preventDefault()}
      onClick={(event) => {
        event.preventDefault();
        event.stopPropagation();
      }}
    >
      <span className="flex h-5 w-5 items-center justify-center rounded-full bg-black/65 shadow-sm">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
          <path d="m12 3.8 2.5 5 5.5.8-4 3.9.9 5.5-4.9-2.6-4.9 2.6.9-5.5-4-3.9 5.5-.8 2.5-5Z" />
        </svg>
      </span>
    </button>
  );
};

