const buildProfileSettingsForm = (profile = {}) => ({
  displayName: limitProfileFullName(profile.fullName || profile.username || profile.name || ''),
  bio: limitProfileStatus(profile.status || profile.bio || ''),
  email: String(profile.email || '').slice(0, EMAIL_MAX_LENGTH),
  phone: sanitizePhoneDigits(profile.phone || ''),
  dob: normalizeDatePickerValue(profile.raw?.dob || profile.raw?.dateOfBirth || profile.dob || ''),
  language: profile.raw?.language || 'English (India)',
  timeZone: profile.raw?.timeZone || 'GMT+05:30 - Asia/Kolkata',
});

const comparableProfileSettingsForm = (formData = {}) => ({
  displayName: limitProfileFullName(formData.displayName || '').trim(),
  bio: limitProfileStatus(formData.bio || ''),
  email: String(formData.email || '').trim().toLowerCase(),
  phone: formData.phone ? normalizePhone(formData.phone) : '',
  dob: String(formData.dob || '').trim(),
  language: String(formData.language || '').trim(),
  timeZone: String(formData.timeZone || '').trim(),
});

const SettingsField = ({ label, children, helper, error }) => (
  <div>
    <label className="mb-2 block text-[13px] font-semibold leading-4 text-[#182236]">{label}</label>
    {children}
    {helper ? <p className="mt-1 text-[12px] leading-5 text-[#1F2937]">{helper}</p> : null}
    {error ? <p className="mt-1 text-[11px] font-medium leading-4 text-[#EF3333]">{error}</p> : null}
  </div>
);

const PROFILE_SETTINGS_IMAGE_TYPES = new Set(['image/jpeg', 'image/png', 'image/jpg']);
const PROFILE_SETTINGS_IMAGE_EXTENSIONS = /\.(jpg|jpeg|png)$/i;
const PROFILE_SETTINGS_IMAGE_ACCEPT = '.jpg,.jpeg,.png,image/jpeg,image/png';

const getProfileSettingsImageFileName = (blob, fallbackName = 'profile') => {
  const mimeType = String(blob?.type || '').toLowerCase();
  const fallbackExtension = String(fallbackName || '').match(/\.([a-z0-9]+)$/i)?.[1]?.toLowerCase();
  const extension =
    mimeType === 'image/png'
        ? 'png'
        : mimeType === 'image/jpeg' || mimeType === 'image/jpg'
          ? 'jpg'
          : fallbackExtension && ['jpg', 'jpeg', 'png'].includes(fallbackExtension)
            ? fallbackExtension
            : 'jpg';

  return `profile.${extension === 'jpeg' ? 'jpg' : extension}`;
};

// Sprint 11 - Story 1: format a stored yyyy-mm-dd date of birth for read-only display.
const formatProfileDob = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return 'Not set';
  const parsed = new Date(`${raw}T00:00:00`);
  if (Number.isNaN(parsed.getTime())) return raw;
  return parsed.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
};

