const TWO_STEP_METHOD_LABELS = {
  authenticator: 'Authenticator App',
  sms: 'SMS Verification',
};

// Short one-liners used by the verification-methods management screen.
const TWO_STEP_METHOD_SHORT_DESC = {
  authenticator: 'Get verification codes from an authenticator app.',
  sms: 'Receive verification codes via SMS to your phone.',
};

// One-time recovery codes are generated on the client â€” the backend has no
// recovery-code endpoint, so we produce a fresh set whenever a user finishes
// enabling 2FA (or asks to regenerate them).
const generateRecoveryCodes = (count = 12) => {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const cryptoRef = globalThis.crypto;
  const randomIndex = (max) => {
    if (cryptoRef?.getRandomValues) {
      const buffer = new Uint32Array(1);
      cryptoRef.getRandomValues(buffer);
      return buffer[0] % max;
    }
    return Math.floor(Math.random() * max);
  };
  const randomBlock = () =>
    Array.from({ length: 4 }, () => alphabet[randomIndex(alphabet.length)]).join('');

  const codes = new Set();
  while (codes.size < count) {
    codes.add(`${randomBlock()}-${randomBlock()}`);
  }
  return Array.from(codes);
};

