const SettingsReportContactModal = ({ contacts = [], currentUserId = '', onSelectContact, onClose }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const normalizedSearchQuery = searchQuery.trim().toLowerCase();
  const reportableContacts = useMemo(() => {
    const seenContactIds = new Set();
    return contacts
      .filter((contact) => {
        const contactUserId = String(getContactUserId(contact) || '').trim();
        if (
          !contactUserId ||
          contactUserId === String(currentUserId || '').trim() ||
          isGroupThreadContact(contact) ||
          isBroadcastThreadContact(contact) ||
          !isRegisteredUser(contact) ||
          seenContactIds.has(contactUserId)
        ) {
          return false;
        }
        seenContactIds.add(contactUserId);
        return true;
      })
      .filter((contact) => {
        if (!normalizedSearchQuery) return true;
        return [contact?.name, contact?.fullName, contact?.phone, contact?.status, contact?.bio]
          .some((value) => String(value || '').toLowerCase().includes(normalizedSearchQuery));
      });
  }, [contacts, currentUserId, normalizedSearchQuery]);

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') onClose?.();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-[320] flex items-center justify-center bg-[rgba(17,24,39,0.42)] px-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="settings-report-contact-title"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose?.();
      }}
    >
      <div className="flex h-[650px] max-h-[calc(100vh-32px)] w-full max-w-[500px] flex-col overflow-hidden rounded-[20px] bg-white shadow-[0_16px_36px_rgba(15,23,42,0.2)]">
        <div className="flex h-[72px] flex-shrink-0 items-center justify-between px-6">
          <h3 id="settings-report-contact-title" className="text-[18px] font-medium leading-6 text-[#111827]">Report Contact</h3>
          <button type="button" onClick={onClose} className="flex h-10 w-10 items-center justify-center rounded-full text-[#71829B] transition-colors hover:bg-[#F8FAFC] hover:text-[#111827]" aria-label="Close report contact">
            <CloseIcon size={20} />
          </button>
        </div>

        <div className="px-6">
          <label className="flex h-[48px] items-center gap-3 rounded-[9px] border border-[#D8E0EB] bg-white px-4 text-[#64748B]">
            <SearchIcon size={20} />
            <input
              value={searchQuery}
              onChange={(event) => setSearchQuery(event.target.value)}
              type="text"
              placeholder="Search contacts"
              className="min-w-0 flex-1 bg-transparent text-[15px] font-medium text-[#334155] outline-none placeholder:text-[#8A98AD]"
              autoFocus
            />
          </label>
        </div>

        <div className="mt-6 flex h-[30px] flex-shrink-0 items-center gap-2.5 px-6 text-[15px] font-semibold text-[#111827]">
          <span>All Contacts</span>
          <span className="rounded-full bg-[#F0E7FF] px-2 py-1 text-[12px] font-semibold text-[#8B5CF6]">{reportableContacts.length}</span>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto px-6 pb-6 pt-3 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {reportableContacts.length ? (
            reportableContacts.map((contact) => {
              const contactKey = String(getContactUserId(contact) || getContactKey(contact));
              const contactName = String(contact?.name || contact?.fullName || contact?.phone || 'Contact').trim();
              const contactSubtitle = String(contact?.status || contact?.bio || contact?.phone || 'Available').trim();
              return (
                <button
                  key={contactKey}
                  type="button"
                  onClick={() => onSelectContact?.(contact)}
                  className="group flex min-h-[76px] w-full items-center gap-4 rounded-[12px] py-3 text-left transition-colors hover:bg-[#F8FAFC]"
                >
                  <img src={resolveContactProfilePicture(contact)} alt="" className="h-12 w-12 flex-shrink-0 rounded-full object-cover" onError={(event) => { event.currentTarget.src = defaultProfilePic; }} />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[16px] font-medium leading-6 text-[#111827]">{contactName}</span>
                    <span className="mt-1 block truncate text-[13px] font-normal leading-5 text-[#64748B]">{contactSubtitle}</span>
                  </span>
                  <span className="mr-1 flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full text-[#64748B] transition-colors group-hover:bg-[#EFF4FA]">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6" /></svg>
                  </span>
                </button>
              );
            })
          ) : (
            <div className="flex h-full items-center justify-center px-8 text-center text-[15px] font-medium leading-6 text-[#64748B]">
              {normalizedSearchQuery ? 'No contacts match your search.' : 'No contacts are available to report.'}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

