// Search the actual controls available inside each settings category, not only
// the category heading. The settings summary API currently returns short keys
// and titles, so this local index makes searches such as "audio", "phone", or
// "wallpaper" lead to the category where that control is available.
const SETTINGS_SEARCH_TERMS_BY_LABEL = Object.freeze({
  Profile: 'account information personal details edit profile avatar photo name bio email phone number date of birth birthday language time zone timezone',
  Appearance: 'theme light dark system colors fonts chat appearance wallpaper background sidebar labels',
  Notification: 'notifications alerts messages groups calls sound audio tone ringtone vibration popup preview badges reminders',
  Privacy: 'privacy security encryption end-to-end two-step verification 2fa blocked contacts disappearing messages default timer report',
  'Media & Links': 'data usage storage media links photos images videos audio documents files download auto-download upload quality cache mobile data wifi roaming',
  Devices: 'devices trusted devices active sessions signed-in login verification remove device',
  'Help & Feedback': 'help support feedback report issue bug contact faq app version',
});

const SETTINGS_REMOTE_KEY_TO_LABEL = Object.freeze({
  profile: 'Profile',
  theme: 'Appearance',
  chatwallpaper: 'Appearance',
  notifications: 'Notification',
  privacysecurity: 'Privacy',
  datausage: 'Media & Links',
  autodownload: 'Media & Links',
});

const SETTINGS_REMOTE_TITLE_TO_LABEL = Object.freeze({
  profile: 'Profile',
  theme: 'Appearance',
  'chat wallpaper': 'Appearance',
  notifications: 'Notification',
  'privacy & security': 'Privacy',
  'data usage & storage': 'Media & Links',
  'auto download media': 'Media & Links',
});

const getSettingsRemoteSearchTerms = (item = {}) => {
  const suppliedTerms = Array.isArray(item?.searchTerms)
    ? item.searchTerms.join(' ')
    : item?.searchTerms;
  const suppliedKeywords = Array.isArray(item?.keywords)
    ? item.keywords.join(' ')
    : item?.keywords;

  return [
    item?.key,
    item?.label,
    item?.title,
    item?.name,
    item?.description,
    item?.subtitle,
    suppliedTerms,
    suppliedKeywords,
  ].filter(Boolean).join(' ');
};

const resolveSettingsRemoteMenuLabel = (item = {}) => {
  const normalizedKey = String(item?.key || '').trim().toLowerCase();
  if (SETTINGS_REMOTE_KEY_TO_LABEL[normalizedKey]) {
    return SETTINGS_REMOTE_KEY_TO_LABEL[normalizedKey];
  }

  const normalizedTitle = String(item?.label || item?.title || item?.name || '').trim().toLowerCase();
  return SETTINGS_REMOTE_TITLE_TO_LABEL[normalizedTitle] || String(item?.label || item?.title || item?.name || '').trim();
};

// Detailed configuration screen shown when a preferences category (Theme, Chat
// Wallpaper, Notifications, Data Usage & Storage, Auto-Download Media) is opened.
// Stories 2-5 will replace this placeholder with the real configuration UI.
const PreferenceCategoryPlaceholder = ({ title, description, icon }) => (
  <div className="flex h-full min-h-0 flex-col bg-white">
    <div className="chatterly-scrollbar min-h-0 flex-1 overflow-y-auto px-7 py-6 lg:px-8">
      <div className="mb-8">
        <h2 className="text-[20px] font-semibold leading-7 text-[#111827]">{title}</h2>
        <p className="mt-1 max-w-[560px] text-[14px] font-medium leading-6 text-[#374151]">{description}</p>
      </div>

      <section className="flex flex-col items-center justify-center rounded-[12px] border border-dashed border-[#D8E0EB] bg-[#F8FAFC] px-6 py-12 text-center">
        <span className="flex h-[52px] w-[52px] items-center justify-center rounded-[12px] bg-white text-[#8B5CF6] shadow-[0_6px_16px_rgba(15,23,42,0.06)]">
          {icon}
        </span>
        <h3 className="mt-4 text-[15px] font-semibold leading-5 text-[#111827]">{title} configuration</h3>
        <p className="mt-2 max-w-[420px] text-[13px] font-medium leading-5 text-[#53657F]">
          This detailed configuration screen is coming soon.
        </p>
      </section>
    </div>
  </div>
);

// Sprint 11 - Story 6: whether the left navigation rail shows text labels under
// each icon. Persisted client-side because the backend preference API does not
// expose a field for it.
const SIDEBAR_LABELS_STORAGE_KEY = 'chatterly_sidebar_labels';
const getAccountPreferenceStorageKey = (key, userId = '') => {
  const normalizedUserId = String(userId || '').trim();
  return normalizedUserId
    ? `user_preference_${encodeURIComponent(normalizedUserId)}_${key}`
    : key;
};
const THEME_OPTIONS = [
  { value: 'light', label: 'Light Mode', description: 'Use Chatterly’s bright appearance.' },
  { value: 'dark', label: 'Dark Mode', description: 'Use a softer, low-light appearance.' },
  { value: 'system', label: 'System Default', description: 'Match your device’s color setting.' },
];

const APPEARANCE_THEME_OPTIONS = [
  { value: 'system', label: 'System Default' },
  { value: 'dark', label: 'Dark' },
  { value: 'light', label: 'Light' },
];

const ThemeSettingsPanel = ({ themePreference = 'light', onSave, onBack }) => {
  const [selectedTheme, setSelectedTheme] = useState(themePreference);

  useEffect(() => setSelectedTheme(themePreference), [themePreference]);

  const previewIsDark = selectedTheme === 'dark' || (
    selectedTheme === 'system' && typeof window !== 'undefined' &&
    window.matchMedia?.('(prefers-color-scheme: dark)').matches
  );

  return (
    <div className="flex h-full min-h-0 flex-col bg-white">
      <div className="chatterly-scrollbar min-h-0 flex-1 overflow-y-auto px-5 py-5 sm:px-8 sm:py-7">
        <button
          type="button"
          onClick={onBack}
          className="mb-5 inline-flex h-10 items-center gap-2 rounded-full px-3 text-[14px] font-semibold text-[#334155] transition-colors hover:bg-[#F1F5F9]"
        >
          <span aria-hidden="true" className="text-xl leading-none">←</span> Back to Settings
        </button>
        <div className="max-w-[760px]">
          <h2 className="text-[24px] font-semibold tracking-[-0.02em] text-[#111827]">Theme</h2>
          <p className="mt-1.5 text-[14px] leading-6 text-[#64748B]">Choose how Chatterly looks. Your preview updates as you make a selection.</p>

          <section className="mt-7 rounded-[24px] border border-[#E2E8F0] bg-[#FAFBFD] p-3 shadow-[0_8px_24px_rgba(15,23,42,0.04)]" aria-label="Theme options">
            {THEME_OPTIONS.map((option) => {
              const isSelected = selectedTheme === option.value;
              return (
                <label key={option.value} className={`flex cursor-pointer items-center gap-4 rounded-[18px] px-4 py-3.5 transition-colors ${isSelected ? 'bg-white shadow-[0_3px_12px_rgba(15,23,42,0.07)]' : 'hover:bg-white/70'}`}>
                  <input type="radio" name="chatterly-theme" value={option.value} checked={isSelected} onChange={() => setSelectedTheme(option.value)} className="h-5 w-5 accent-[#7C3AED]" />
                  <span className="min-w-0">
                    <span className="block text-[15px] font-semibold text-[#172033]">{option.label}</span>
                    <span className="mt-0.5 block text-[13px] leading-5 text-[#64748B]">{option.description}</span>
                  </span>
                </label>
              );
            })}
          </section>

          <section className={`mt-7 overflow-hidden rounded-[24px] border p-4 shadow-[0_12px_28px_rgba(15,23,42,0.10)] transition-colors ${previewIsDark ? 'border-[#3B465B] bg-[#151B29]' : 'border-[#E2E8F0] bg-white'}`} aria-label="Live chat preview">
            <p className={`mb-4 text-[12px] font-semibold uppercase tracking-[0.12em] ${previewIsDark ? 'text-[#A9B8D0]' : 'text-[#64748B]'}`}>Live preview</p>
            <div className={`rounded-[18px] p-4 ${previewIsDark ? 'bg-[#202938]' : 'bg-[#F7F8FC]'}`}>
              <div className="flex items-center gap-3 border-b border-current/10 pb-3">
                <span className="flex h-9 w-9 items-center justify-center rounded-full bg-[#8B5CF6] text-[14px] font-bold text-white">A</span>
                <span><span className={`block text-[14px] font-semibold ${previewIsDark ? 'text-white' : 'text-[#172033]'}`}>Alex Morgan</span><span className="block text-[12px] text-[#22C55E]">Online</span></span>
              </div>
              <div className="space-y-3 py-5 text-[13px]">
                <div className={`w-fit max-w-[80%] rounded-[16px] rounded-tl-[4px] px-3.5 py-2.5 ${previewIsDark ? 'bg-[#303C51] text-[#F4F7FB]' : 'bg-white text-[#334155] shadow-sm'}`}>Hey! Are we still on for today?</div>
                <div className="ml-auto w-fit max-w-[80%] rounded-[16px] rounded-tr-[4px] bg-[#7C3AED] px-3.5 py-2.5 text-white">Absolutely, see you at 4 PM!</div>
              </div>
              <div className={`rounded-full px-4 py-2.5 text-[13px] ${previewIsDark ? 'bg-[#303C51] text-[#98A8C1]' : 'bg-white text-[#94A3B8] shadow-sm'}`}>Write a message…</div>
            </div>
          </section>
        </div>
      </div>
      <div className="flex justify-end border-t border-[#E2E8F0] bg-white px-5 py-4 sm:px-8">
        <button type="button" onClick={() => onSave(selectedTheme)} className="h-11 rounded-full bg-[#7C3AED] px-6 text-[14px] font-semibold text-white shadow-[0_8px_18px_rgba(124,58,237,0.28)] transition-colors hover:bg-[#6D28D9]">Save Changes</button>
      </div>
    </div>
  );
};

// Sprint 11 - Story 6: Appearance screen. Consolidates Theme, Chat Wallpaper and
// the new Side bar label toggle into one screen that matches the Sprint 11 design.
const AppearanceSettingRow = ({ icon, title, description, children }) => (
  <div className="chatterly-appearance-row flex items-center justify-between gap-4 border-b py-4 last:border-b-0">
    <div className="flex min-w-0 items-center gap-3">
      <span className="chatterly-appearance-icon flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-[9px]" aria-hidden="true">{icon}</span>
      <div className="min-w-0">
        <p className="chatterly-appearance-title text-[14px] font-semibold leading-5">{title}</p>
        <p className="chatterly-appearance-description mt-0.5 text-[12px] leading-[17px]">{description}</p>
      </div>
    </div>
    <div className="flex flex-shrink-0 items-center">{children}</div>
  </div>
);

