  const [formData, setFormData] = useState(emptyAddContactForm);
  const [activeTab, setActiveTab] = useState('All');
  const [isPermissionModalOpen, setIsPermissionModalOpen] = useState(false);
  const [contactSaveDecision, setContactSaveDecision] = useState(null);
  const [isContactSaveDecisionBusy, setIsContactSaveDecisionBusy] = useState(false);
  const [currentUserProfile, setCurrentUserProfile] = useState(() => normalizeProfile({}, storedUser));
  const currentUserId =
    currentUserProfile?.userId || currentUserProfile?.id || currentUserProfile?._id ||
    storedUser?.userId || storedUser?.id || storedUser?._id || 'me';
  const [chatDrafts, setChatDrafts] = useState(() => readStoredChatDrafts(currentUserId));
