  const navigateToContactThread = useCallback((contact, targetChatId) => {
    const didPreserveActiveCall = preserveActiveCallForNavigation({ displayMode: 'card' });
    const nextModule = resolveContactThreadModule(contact, currentModule);
    const normalizedTargetChatId = String(targetChatId || '').trim();

    // Update the active conversation in the same event as the route change.
    // Previously this was left to the route-sync effect, which could retain the
    // previous contact until a reload when contacts changed in quick succession.
    if (contact && normalizedTargetChatId) {
      const nextContact = isGroupThreadContact(contact)
        ? contact
        : {
            ...contact,
            chatId: normalizedTargetChatId,
            type: 'chat',
            chatType: 'chat',
            isGroup: false,
            isBroadcast: false,
          };
      setSelectedContact(nextContact);
      shouldStickToBottomRef.current = true;
      previousChatIdRef.current = null;
      previousMessageCountRef.current = 0;
    }

    // Opening a chat from the Calls view returns to the chats view so the
    // conversation (not the call-log panel) is shown.
    if (sidebarView === 'calls') {
      setSidebarView('chats');
    }
    navigate(
      buildChatThreadRoute(normalizedTargetChatId, nextModule),
      didPreserveActiveCall ? { state: location.state } : undefined
    );
  }, [
    currentModule,
    location.state,
    navigate,
    preserveActiveCallForNavigation,
    sidebarView,
  ]);

