                    <path d="M41.83 40.54C40.67 33.91 35.8 28 24 28C12.2 28 7.33001 33.91 6.17001 40.54C5.93001 41.9 6.94001 43 8.32001 43H39.68C41.06 43 42.07 41.9 41.83 40.54Z" fill="url(#paint1_linear)"/>
                    <defs>
