                      <label htmlFor="phoneInput" className={`pointer-events-none absolute left-4 top-0 -translate-y-1/2 bg-white px-1 text-[12px] transition-all peer-placeholder-shown:top-1/2 peer-placeholder-shown:text-[15px] peer-placeholder-shown:text-[#6B7280] peer-focus:top-0 peer-focus:text-[12px] ${addContactValidationMessage ? 'text-red-500' : 'text-[#A855F7]'}`}>Phone number <span className="text-red-500">*</span></label>
